-- =============================================================================
-- 421 — LE CAHIER D'EXERCICES DE 6E
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/6e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 421 --niveau 6e > supabase/contenu/421_exercices_6e.sql
--
-- 51 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   anglais.1                6 exercices · 2 chapitres
--   anglais.2                6 exercices · 2 chapitres
--   emc.1                    3 exercices · 1 chapitres
--   francais                 3 exercices · 1 chapitres
--   histoire-geo             3 exercices · 1 chapitres
--   histoire-geo.2           6 exercices · 2 chapitres
--   histoire-geo.3           3 exercices · 1 chapitres
--   histoire-geo.4           3 exercices · 1 chapitres
--   histoire-geo.5           3 exercices · 1 chapitres
--   maths                    3 exercices · 1 chapitres
--   maths.2                  6 exercices · 2 chapitres
--   maths.3                  3 exercices · 1 chapitres
--   sport.1                  3 exercices · 1 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une carte postale du pays de Galles","competence":"comprendre-langue","situation":"Sam, le correspondant anglais d’Inès, passe les vacances dans la ferme de son grand-père, au pays de Galles. Il lui envoie une carte postale pleine d’animaux.","documents":[{"id":"carte","type":"texte","genre":"lettre","titre":"Sam’s postcard","source":"Carte imaginée pour l’exercice","blocs":["Dear Inès,","I’m at my grandad’s farm in Wales for the holidays. It’s great! There are two horses, four cows, twenty sheep and three cats. There are mice in the barn, so the cats are very happy!","My little cousins, Owen and Megan, are here too. The two children help Grandad every morning.","See you soon,","Sam"]}],"questions":[{"enonce":"Sam écrit **trois** noms au pluriel qui ne se terminent **pas** par -s. Touche-les.","aide":"Ce sont des pluriels irréguliers : deux animaux… et des personnes. Relis les paragraphes 2 et 3.","type":"zone","document":"carte","multiple":true},{"enonce":"Combien de moutons y a-t-il à la ferme ?","aide":"*Sheep* veut dire « mouton » : cherche le nombre écrit juste devant ce mot.","type":"nombre","unite":"moutons"},{"enonce":"Complète le résumé de la carte avec le bon pluriel.","aide":"Relis le paragraphe 2 : chaque animal y est écrit avec son nombre. Attention, trois mots de la banque n’existent pas !","type":"trous","segments":["On the farm, there are four ",0," and twenty ",1,". There are ",2," in the barn!"],"banque":["mouses","sheeps","sheep","cows","mice","cowes"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21","m27","m48"]},"explication":"**sheep** (*one sheep, twenty sheep* : il ne change pas), **mice** (pluriel de *a mouse*) et **children** (pluriel de *a child*) sont des pluriels irréguliers : pas de -s."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 moutons","explication":"Il y a **20** moutons : *twenty sheep*. Et *sheep* ne prend jamais de -s, même après *twenty*."},{"cle":{"type":"trous","trous":[["cows"],["sheep"],["mice"]]},"affichage":"cows · sheep · mice","explication":"four **cows** (pluriel régulier en -s), twenty **sheep** (invariable) et **mice** (pluriel irrégulier de *mouse*). *Sheeps*, *mouses* et *cowes* n’existent pas."}]$ex$::jsonb),
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La salade de fruits de Granny Rose","competence":"analyser-document","situation":"Pour la kermesse de son école, à Brighton, Lucy prépare la salade de fruits de sa grand-mère. Voici la recette, recopiée sur une vieille fiche.","documents":[{"id":"recette","type":"fiche","modele":"recette","titre":"La fiche de Granny Rose","source":"Recette imaginée pour l’exercice","entete":"Granny Rose’s Fruit Salad","sousTitre":"Serves 8 people","emoji":"🍓","teinte":"corail","lignes":[{"texte":"**You need:**"},{"texte":"4 apples","id":"z1"},{"texte":"2 peaches","id":"z2"},{"texte":"3 bananas","id":"z3"},{"texte":"12 cherries","id":"z4"},{"texte":"a few strawberries","id":"z5"},{"texte":"some orange juice","id":"z6"},{"texte":"a little sugar","id":"z7"},{"separateur":true},{"texte":"**Tools:** 2 knives and a big bowl"},{"separateur":true},{"texte":"Cut the fruit into small pieces. Add the juice and the sugar. Put the bowl in the fridge for an hour."}],"pied":"Easy and yummy! — Granny Rose"}],"questions":[{"enonce":"Deux ingrédients sont **indénombrables** : on ne peut pas les compter un par un. Touche leurs **deux** lignes.","aide":"Peut-on dire « two sugars » ou « three juices » dans une recette ? Regarde aussi les mots placés devant chaque ingrédient.","type":"zone","document":"recette","multiple":true},{"enonce":"La recette est pour huit personnes. Quel mot anglais, sous le titre, veut dire « personnes » ?","aide":"Cherche sous le titre de la fiche, juste après le nombre 8.","type":"texte","placeholder":"Un mot"},{"enonce":"Range les pluriels de la recette selon la règle qu’ils suivent.","aide":"Pense au singulier de chaque mot : *a peach*, *a cherry*, *a knife*… Par quelles lettres finit-il ?","type":"categories","categories":[{"id":"c0","texte":"On ajoute -s"},{"id":"c1","texte":"On ajoute -es"},{"id":"c2","texte":"-y devient -ies"},{"id":"c3","texte":"-f(e) devient -ves"}],"items":[{"id":"i0","texte":"strawberries"},{"id":"i1","texte":"peaches"},{"id":"i2","texte":"apples"},{"id":"i3","texte":"pieces"},{"id":"i4","texte":"cherries"},{"id":"i5","texte":"knives"},{"id":"i6","texte":"bananas"}]},{"enonce":"Dans quel mot de la recette le -s final se prononce-t-il /ɪz/, comme une syllabe de plus ?","aide":"Le pluriel ajoute une syllabe après un « sifflement » : s, sh, ch, x…","type":"choix","options":[{"id":"a","texte":"cherries"},{"id":"b","texte":"bananas"},{"id":"c","texte":"peaches"},{"id":"d","texte":"apples"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z6","z7"]},"explication":"**some orange juice** et **a little sugar** : le jus et le sucre ne se comptent pas. Comme *water* ou *bread*, ces noms n’ont ni pluriel ni *a/an*."},{"cle":{"type":"texte","acceptes":["people"]},"affichage":"people","explication":"**people** : c’est le pluriel irrégulier de *a person*. *Serves 8 people* veut dire « pour 8 personnes »."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c1","i2":"c0","i3":"c0","i4":"c2","i5":"c3","i6":"c0"}},"explication":"**-s** : apples, bananas, pieces · **-es** après -ch : peaches · **-ies** après consonne + y : cherries, strawberries · **-ves** : knives (*a knife*)."},{"cle":{"type":"choix","ids":["c"]},"explication":"**peaches** se dit « pi-tchiz » : après le son « tch », le pluriel forme une syllabe /ɪz/, comme *buses* ou *watches*. Dans *apples*, *bananas* et *cherries*, le -s se prononce /z/."}]$ex$::jsonb),
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une journée à Dino World","competence":"manier-langue","situation":"Harry, le correspondant anglais de Léo, passe la journée dans un parc de dinosaures. Il envoie à Léo la photo de l’affiche pour son exposé d’anglais… mais Léo fait encore quelques erreurs.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"L’affiche du parc","source":"Affiche imaginée pour l’exercice","entete":"DINO WORLD","sousTitre":"Brighton · Open every day, 10 am – 6 pm","emoji":"🦖","teinte":"vert","lignes":[{"texte":"Meet **30 giant dinosaurs** in the forest!"},{"texte":"See a T. rex and its **60 teeth**!"},{"texte":"Put your **feet** in giant footprints!"},{"separateur":true},{"texte":"Tickets — adults:","valeur":"£12"},{"texte":"Tickets — children (4–15):","valeur":"£8"},{"texte":"Under 4:","valeur":"free"}],"pied":"Picnic area · Gift shop · Café"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Harry et Léo","participants":[{"nom":"Harry","emoji":"👦","cote":"gauche"},{"nom":"Léo","emoji":"🧒","cote":"droite"}],"repliques":[{"qui":"Harry","texte":"Hi Léo! I’m at Dino World with my mum and my two little brothers 🦖"},{"qui":"Léo","texte":"Cool! Are the dinosaurs big?"},{"qui":"Harry","texte":"Yes, they’re huge! The T. rex is my favourite 😱"},{"qui":"Léo","texte":"Can you send me some informations about the park? It’s for my English project."},{"qui":"Harry","texte":"Sure! Look at the poster 📸"},{"qui":"Léo","texte":"Thanks! I can’t go out today: I’ve got a lot of homeworks 😩"},{"qui":"Harry","texte":"Poor you! 😅"}]}],"questions":[{"enonce":"Léo fait **deux** fautes de pluriel dans ses messages. Touche les deux mots fautifs.","aide":"Cherche deux noms qui prennent un -s en français, mais qui sont **indénombrables** en anglais.","type":"zone","document":"sms","multiple":true},{"enonce":"Pour son exposé, Léo trie des noms des deux documents. Range-les.","aide":"Demande-toi si l’on peut dire « two … » : two tickets ? two informations ?","type":"categories","categories":[{"id":"c0","texte":"Dénombrable : a/an et pluriel"},{"id":"c1","texte":"Indénombrable : ni a/an, ni pluriel"}],"items":[{"id":"i0","texte":"ticket"},{"id":"i1","texte":"brother"},{"id":"i2","texte":"homework"},{"id":"i3","texte":"dinosaur"},{"id":"i4","texte":"footprint"},{"id":"i5","texte":"information"}]},{"enonce":"Harry (12 ans), ses deux petits frères (7 et 9 ans) et leur mère achètent leurs billets. Combien paient-ils en tout ?","aide":"Sur l’affiche, trouve le prix pour les *children* et pour les *adults*. Combien y a-t-il d’enfants ?","type":"nombre","unite":"£"},{"enonce":"Complète la fiche d’exposé de Léo : écris au pluriel le nom entre parenthèses.","aide":"Un seul de ces pluriels est régulier. Les trois autres changent de voyelle ou de terminaison : l’affiche peut t’aider.","type":"trous","segments":["At Dino World, there are 30 giant ",0," (dinosaur). A T. rex has got 60 ",1," (tooth)! ",2," (child) under 4 don’t pay, and you can put your ",3," (foot) in giant footprints."]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33","m58"]},"explication":"**informations** et **homeworks** sont faux : en anglais, *information* et *homework* sont **indénombrables**. Léo aurait dû écrire *some information* et *a lot of homework*."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"On compte les **dinosaurs**, les **tickets**, les **footprints** et les **brothers**. *Information* et *homework* sont **indénombrables** : *some information*, *a lot of homework*."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 £","explication":"3 enfants × 8 £ + 1 adulte × 12 £ = 24 + 12 = **36 £**."},{"cle":{"type":"trous","trous":[["dinosaurs"],["teeth"],["children"],["feet"]]},"affichage":"dinosaurs · teeth · children · feet","explication":"**dinosaurs** (régulier), **teeth** (*a tooth*), **Children** (*a child*) et **feet** (*a foot*) : trois pluriels irréguliers à connaître par cœur."}]$ex$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le pique-nique de Ben","competence":"observer-schema","situation":"Ben, un petit Londonien, prépare un pique-nique à Hyde Park avec sa grande sœur. Voici tout ce qu’il a posé sur la nappe, avec le nom anglais de chaque objet.","documents":[{"id":"nappe","type":"schema","titre":"On the picnic blanket","largeur":320,"hauteur":240,"elements":[{"forme":"rect","x":12,"y":12,"l":296,"h":216,"arrondi":16,"teinte":"rose","motif":"clair"},{"forme":"emoji","x":50,"y":58,"emoji":"🍎","taille":32},{"forme":"emoji","x":123,"y":58,"emoji":"🥪","taille":32},{"forme":"emoji","x":197,"y":58,"emoji":"🥚","taille":32},{"forme":"emoji","x":270,"y":58,"emoji":"🍌","taille":32},{"forme":"rect","id":"z1","zone":true,"x":18,"y":84,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"apple"},{"forme":"rect","id":"z2","zone":true,"x":91,"y":84,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"sandwich"},{"forme":"rect","id":"z3","zone":true,"x":165,"y":84,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"egg"},{"forme":"rect","id":"z4","zone":true,"x":238,"y":84,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"banana"},{"forme":"emoji","x":50,"y":152,"emoji":"☂️","taille":32},{"forme":"emoji","x":123,"y":152,"emoji":"🍰","taille":32},{"forme":"emoji","x":197,"y":152,"emoji":"🍊","taille":32},{"forme":"emoji","x":270,"y":152,"emoji":"⚽","taille":32},{"forme":"rect","id":"z5","zone":true,"x":18,"y":178,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"umbrella"},{"forme":"rect","id":"z6","zone":true,"x":91,"y":178,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"cake"},{"forme":"rect","id":"z7","zone":true,"x":165,"y":178,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"orange"},{"forme":"rect","id":"z8","zone":true,"x":238,"y":178,"l":64,"h":26,"arrondi":9,"teinte":"blanc","motif":"plein","texte":"ball"}]}],"questions":[{"enonce":"Ben doit écrire *a* ou *an* devant chaque objet. Touche les étiquettes des **quatre** objets devant lesquels il faut écrire **an**.","aide":"Dis chaque mot à voix haute : commence-t-il par un **son** de voyelle (a, e, i, o, u) ?","type":"zone","document":"nappe","multiple":true},{"enonce":"Ben écrit un message à sa sœur. Complète-le avec *a*, *an* ou *the*.","aide":"D’abord on présente un objet avec *a* ou *an* ; ensuite, quand on sait de quel objet on parle, on le désigne.","type":"trous","segments":["In my bag, I’ve got ",0," banana and ",1," apple. ",2," apple is red!"],"banque":["the","a","an"]},{"enonce":"Le pique-nique commence dans une heure. Comment Ben écrit-il « dans une heure » ?","aide":"Dans *hour*, le **h** ne se prononce pas. Quel est donc le premier son du mot ?","type":"choix","options":[{"id":"a","texte":"in hour"},{"id":"b","texte":"in an hour"},{"id":"c","texte":"in the hour"},{"id":"d","texte":"in a hour"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1","z3","z5","z7"]},"explication":"**an apple**, **an egg**, **an umbrella**, **an orange** : ces mots commencent par un son de voyelle. On dit en revanche *a sandwich*, *a banana*, *a cake* et *a ball*."},{"cle":{"type":"trous","trous":[["a"],["an"],["the"]]},"affichage":"a · an · the","explication":"*a banana* et *an apple* : Ben les **présente**. Puis ***The** apple is red* : il parle de la pomme qu’il vient de citer."},{"cle":{"type":"choix","ids":["b"]},"explication":"**in an hour** : on n’entend pas le *h* de *hour*, le mot commence par un son de voyelle. C’est toujours le **son**, et non la lettre, qui décide."}]$ex$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le premier e-mail de Charlie","competence":"analyser-texte","situation":"Lina vient d’avoir un correspondant anglais, Charlie, qui habite à Manchester. Voici le premier e-mail qu’il lui envoie.","documents":[{"id":"mail","type":"texte","genre":"lettre","titre":"Charlie’s e-mail","source":"E-mail imaginé pour l’exercice","blocs":["Hi Lina,","My name is Charlie. I’m twelve and I live in Manchester, in the north of England. I’ve got a sister and a dog. The dog is called Biscuit, and he loves cheese!","I go to school by bus. My favourite subject is history. I play football with my cousin in the park, and I love music.","What about you? Write soon!","Charlie"]}],"questions":[{"enonce":"Dans le paragraphe 3, Charlie emploie **quatre** noms **sans article**, là où le français en mettrait un (« l’ », « la », « au »…). Touche-les.","aide":"Cherche les noms qui n’ont devant eux ni *a/an*, ni *the*, ni *my*. Attention : « en bus » n’a pas d’article en français non plus.","type":"zone","document":"mail","multiple":true,"portee":[2]},{"enonce":"Pourquoi Charlie écrit-il « **The** dog is called Biscuit », et non « A dog is called Biscuit » ?","aide":"Relis la phrase d’avant : « I’ve got a sister and a dog. »","type":"choix","options":[{"id":"a","texte":"Parce que *dog* commence par une consonne"},{"id":"b","texte":"Parce qu’il a déjà présenté son chien juste avant"},{"id":"c","texte":"Parce qu’on met toujours *the* devant un animal"},{"id":"d","texte":"Parce que Biscuit est un nom propre"}],"multiple":false},{"enonce":"Lina répond à Charlie. Complète son message avec *a*, *an* ou *the*.","aide":"Fais comme Charlie avec son chien : on présente avec *a/an*, on désigne avec *the*. Et écoute le premier son du mot qui suit.","type":"trous","segments":["Hi Charlie! I live in Lyon. I’ve got ",0," brother and ",1," hamster. ",2," hamster is called Noisette. And my brother wants ",3," iguana!"],"banque":["an","the","a"]},{"enonce":"Lina veut écrire : « Mon pays préféré, c’est la France. » Complète sa phrase : « My favourite country is ___. »","aide":"Charlie écrit « in Manchester », « of England »… Met-il un article devant un nom de ville ou de pays ?","type":"texte","placeholder":"Le mot qui manque"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m37","m44","m47","m57"]},"explication":"**school**, **history**, **football** et **music** : pas d’article devant *school* dans sa fonction, les matières, les sports et les indénombrables pris en général. Le français dit pourtant « à l’école », « l’histoire », « au foot », « la musique »."},{"cle":{"type":"choix","ids":["b"]},"explication":"Charlie **présente** d’abord son chien (*a dog*), puis il le **désigne** : ***the** dog*, le chien dont on vient de parler."},{"cle":{"type":"trous","trous":[["a"],["a"],["the"],["an"]]},"affichage":"a · a · the · an","explication":"**a** brother, **a** hamster (son de consonne : le *h* s’entend) ; ***The** hamster* : il vient d’être présenté ; **an** iguana : *iguana* commence par un son de voyelle."},{"cle":{"type":"texte","acceptes":["france"]},"affichage":"France","explication":"*My favourite country is* **France** : pas d’article devant un nom de pays, de ville ou de langue, alors que le français dit « **la** France »."}]$ex$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"De New York à Amsterdam","competence":"analyser-document","situation":"Jade, une collégienne française, passe ses vacances à New York. Elle envoie une carte postale à son correspondant anglais, Tom, qui est lui-même aux Pays-Bas. Puis ils s’écrivent par SMS.","documents":[{"id":"carte","type":"fiche","modele":"carte-postale","titre":"La carte postale de Jade","source":"Carte imaginée pour l’exercice","entete":"Greetings from New York!","emoji":"🗽","teinte":"bleu","lignes":[{"texte":"Hi Tom!"},{"texte":"We’re in the United States for two weeks, and New York is fantastic!"},{"texte":"We have breakfast in a café every morning, and I speak English all day."},{"texte":"Tomorrow: a bike ride in Central Park. And next summer: the United Kingdom!"}],"pied":"Love, Jade"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Jade et Tom","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Tom","texte":"Hi Jade! How is New York? 🗽"},{"qui":"Jade","texte":"Amazing! Our hotel is next to Central Park. And you?"},{"qui":"Tom","texte":"I’m in the Netherlands with my dad. We’re in Amsterdam for a week 🚲"},{"qui":"Jade","texte":"Cool! Do you speak Dutch? 😄"},{"qui":"Tom","texte":"No! My cousins speak English with me. Tomorrow we play the tennis in the park 🎾"},{"qui":"Jade","texte":"Have fun!"}]}],"questions":[{"enonce":"Dans ses messages, Tom met **un** article de trop. Touche-le.","aide":"Relis la règle de l’article zéro : repas, sports, matières… Mais attention, certains pays prennent bien *the*.","type":"zone","document":"sms","multiple":false},{"enonce":"Range ces noms des deux documents : sont-ils précédés de *the*, ou d’aucun article ?","aide":"Les villes, les langues, les repas et les sports n’ont pas d’article. Quels noms de pays font exception ?","type":"categories","categories":[{"id":"c0","texte":"the"},{"id":"c1","texte":"Pas d’article"}],"items":[{"id":"i0","texte":"United Kingdom"},{"id":"i1","texte":"Amsterdam"},{"id":"i2","texte":"Netherlands"},{"id":"i3","texte":"New York"},{"id":"i4","texte":"English"},{"id":"i5","texte":"breakfast"},{"id":"i6","texte":"tennis"},{"id":"i7","texte":"United States"}]},{"enonce":"Pourquoi Jade écrit-elle « **the** United States », alors qu’on écrit « France » sans article ?","aide":"Que veut dire le mot *states* ? Relis les exceptions du cours.","type":"choix","options":[{"id":"a","texte":"Parce que le nom contient un nom commun au pluriel : *states*, les « États »"},{"id":"b","texte":"Parce que Jade fait une faute d’anglais"},{"id":"c","texte":"Parce que tous les pays d’Amérique prennent *the*"},{"id":"d","texte":"Parce que les États-Unis sont plus grands que la France"}],"multiple":false},{"enonce":"Jade envoie un dernier message. Complète-le avec *a* ou *an*.","aide":"Regarde le mot qui suit **juste** le trou : c’est son premier son qui décide, même si c’est un adjectif.","type":"trous","segments":["New York is ",0," amazing city! We’ve got ",1," small room in ",2," old hotel, and tonight we’ve got tickets for ",3," musical on Broadway!"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m44"]},"explication":"On dit *play* **tennis**, sans article : c’est un sport. Le français dit « jouer **au** tennis », d’où la faute. En revanche, *the Netherlands* et *the park* sont justes."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c1","i4":"c1","i5":"c1","i6":"c1","i7":"c0"}},"explication":"**the** United States, **the** Netherlands, **the** United Kingdom : des pays au nom pluriel ou qui contient un nom commun. **Aucun article** devant les villes (*New York*, *Amsterdam*), les langues (*English*), les repas (*breakfast*) et les sports (*tennis*)."},{"cle":{"type":"choix","ids":["a"]},"explication":"*The United States* = « les États-Unis » : le nom contient un nom commun (*states*) au pluriel, comme *the Netherlands*. *The United Kingdom* contient lui aussi un nom commun : *kingdom*, le royaume."},{"cle":{"type":"trous","trous":[["an"],["a"],["an"],["a"]]},"affichage":"an · a · an · a","explication":"**an** amazing city, **a** small room, **an** old hotel, **a** musical : on choisit *a* ou *an* d’après le son du mot qui suit immédiatement, nom ou adjectif."}]$ex$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le grand frère d’Emily","competence":"comprendre-langue","situation":"Léo, en 6e à Lyon, a une nouvelle correspondante anglaise : Emily, qui habite à Brighton. Elle lui parle de sa famille par SMS.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages d’Emily et de Léo","participants":[{"nom":"Emily","emoji":"👧","cote":"gauche"},{"nom":"Léo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léo","texte":"Hi Emily! Have you got any brothers or sisters?"},{"qui":"Emily","texte":"Yes, one big brother. His name is Jack and he’s 15 😎"},{"qui":"Emily","texte":"He plays the drums in a band 🥁 and he watches horror films every Friday night 🙈"},{"qui":"Léo","texte":"Cool! Do you watch them with him?"},{"qui":"Emily","texte":"No way! I hate horror films 😱 I read in my room."}]}],"questions":[{"enonce":"Touche les **deux verbes** qui disent ce que Jack fait de son temps libre.","aide":"Cherche le message où Emily parle de la batterie (*the drums*). Avec *he*, le verbe au présent simple porte une marque à la fin.","type":"zone","document":"sms","multiple":true},{"enonce":"Que fait Emily le vendredi soir, pendant que Jack regarde ses films ?","aide":"Relis le dernier message d’Emily : que fait-elle *in my room* ?","type":"choix","options":[{"id":"a","texte":"Elle joue de la batterie"},{"id":"b","texte":"Elle regarde les films avec lui"},{"id":"c","texte":"Elle lit dans sa chambre"},{"id":"d","texte":"Elle joue du piano"}],"multiple":false},{"enonce":"À son tour, Léo parle de sa grande sœur, Chloé. Complète son message avec la bonne forme du verbe.","aide":"Le sujet est *she* : le verbe prend un -s. Et un verbe terminé par -ch prend… -es !","type":"trous","segments":["My sister Chloé is 16. She ",0," the guitar and she ",1," TV series every evening."],"banque":["watches","plays","play","watch","watchs"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21","m29"]},"explication":"**plays** et **watches** : avec *he* (Jack), le verbe du présent simple prend un **-s**, et même **-es** après -ch."},{"cle":{"type":"choix","ids":["c"]},"explication":"Elle **lit dans sa chambre** : *I read in my room*. Elle déteste les films d’horreur (*I hate horror films*) !"},{"cle":{"type":"trous","trous":[["plays"],["watches"]]},"affichage":"plays · watches","explication":"She **plays** the guitar and she **watches** TV series : avec *she*, on ajoute **-s**, et **-es** après -ch (*watch → watches*)."}]$ex$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"L’enquête de la classe de Leeds","competence":"lire-tableau","situation":"Dans un collège de Leeds, les élèves de *Year 7* (l’équivalent de la 6e) ont répondu à une enquête sur leur semaine. Voici les réponses de trois d’entre eux : ✓ = oui, ✗ = non.","documents":[{"id":"enquete","type":"tableau","titre":"Class survey: our week","source":"Enquête imaginée pour l’exercice.","colonnes":["Every week, I…","Amy","Ben","Zoe"],"lignes":[["walk to school","✓","✗","✓"],["study Spanish","✓","✗","✗"],["wash the dishes","✓","✓","✗"],["go to the cinema","✓","✗","✓"],["play the guitar","✗","✗","✓"]],"enteteLignes":true}],"questions":[{"enonce":"Le professeur résume les réponses d’**Amy**. Complète avec la bonne forme du verbe au présent simple.","aide":"Consonne + y devient -ies ; après -sh et après -o, on ajoute -es.","type":"trous","segments":["Every week, Amy ",0," Spanish, she ",1," the dishes and she ",2," to the cinema."],"banque":["washs","goes","studys","studies","study","gos","go","washes"]},{"enonce":"Quelle phrase sur **Ben** est juste, d’après le tableau ?","aide":"Regarde la case de Ben sur la ligne *walk to school*. Puis rappelle-toi : le -s de la 3e personne ne se met qu’une fois.","type":"choix","options":[{"id":"a","texte":"Ben doesn’t walk to school."},{"id":"b","texte":"Ben don’t walk to school."},{"id":"c","texte":"Ben doesn’t walks to school."},{"id":"d","texte":"Ben walks to school."}],"multiple":false},{"enonce":"Zoe parle d’elle-même : « I ___ Spanish: I study German. » Écris les mots qui manquent.","aide":"Zoe a une croix pour *study Spanish*. Avec *I*, la négation se fait avec l’auxiliaire *do*.","type":"texte","placeholder":"I … Spanish"},{"enonce":"Ben affirme : « I don’t play the guitar. » Touche la case du tableau qui le prouve.","aide":"Trouve la ligne *play the guitar*, puis la colonne de Ben.","type":"zone","document":"enquete","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"trous","trous":[["studies"],["washes"],["goes"]]},"affichage":"studies · washes · goes","explication":"Amy **studies** (consonne + y → -ies), she **washes** (-sh → -es) and she **goes** (-o → -es)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Ben a une croix : il ne va pas au collège à pied. **Ben doesn’t walk to school** : *doesn’t* avec *he*, et le verbe perd son -s."},{"cle":{"type":"texte","acceptes":["don t study","do not study","dont study"]},"affichage":"don’t study","explication":"« I **don’t study** Spanish » : avec *I*, on emploie **don’t** (*do not*) + la base verbale."},{"cle":{"type":"zone","ids":["r4c2"]},"explication":"La **croix de Ben** sur la ligne *play the guitar* le prouve : il ne joue pas de la guitare (*he doesn’t play the guitar*)."}]$ex$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Kirsty, la bergère de l’île de Skye","competence":"analyser-texte","situation":"Kirsty, 11 ans, vit dans une ferme de l’île de Skye, en Écosse. Elle raconte sa journée sur le blog de son école. Un journaliste du journal local veut écrire un article sur elle.","documents":[{"id":"blog","type":"texte","genre":"recit","titre":"Kirsty’s blog: my school day","source":"Texte imaginé pour l’exercice.","blocs":["My name is Kirsty and I live on a sheep farm on the Isle of Skye. I get up at half past six every morning. First, I feed the sheep with my dad. Then I have breakfast: I always eat porridge!","I catch the school bus at quarter to eight. The journey is long, so I usually read a book. I am never late for school.","After school, I do my homework and I play with our dog, Bramble. At the weekend, I sometimes help my mum at the market."]},{"id":"horloge","type":"horloge","titre":"Un matin d’école, chez Kirsty","heures":7,"minutes":45,"numerique":false}],"questions":[{"enonce":"Regarde l’horloge (Doc 2). Que fait Kirsty à cette heure-là ?","aide":"La petite aiguille est presque sur le 8, la grande sur le 9 : il est 8 h moins le quart. Comment le dit-on en anglais ? Cherche-le dans le blog.","type":"choix","options":[{"id":"a","texte":"She feeds the sheep."},{"id":"b","texte":"She gets up."},{"id":"c","texte":"She does her homework."},{"id":"d","texte":"She catches the school bus."}],"multiple":false},{"enonce":"Dans le blog, touche les **quatre** mots qui disent **à quelle fréquence** Kirsty fait les choses.","aide":"Ce sont de petits mots placés juste avant le verbe… ou juste après *am*.","type":"zone","document":"blog","multiple":true},{"enonce":"Le journaliste écrit son article à la 3e personne. Complète-le en conjuguant les verbes au présent simple.","aide":"Avec *Kirsty* ou *she*, le verbe prend un -s… et -es après -ch.","type":"trous","segments":["Kirsty ",0," (get) up at half past six. She ",1," (feed) the sheep with her dad and she ",2," (catch) the school bus at quarter to eight."]},{"enonce":"Le journaliste demande : « Does Kirsty walk to school? » Choisis la bonne réponse courte.","aide":"Comment Kirsty va-t-elle à l’école ? Relis le paragraphe 2. La réponse courte reprend l’auxiliaire de la question.","type":"choix","options":[{"id":"a","texte":"No, she doesn’t walks."},{"id":"b","texte":"Yes, she does."},{"id":"c","texte":"No, she don’t."},{"id":"d","texte":"No, she doesn’t."}],"multiple":false},{"enonce":"Remets les mots dans l’ordre pour écrire une phrase juste de l’article.","aide":"Avec le verbe *be*, le mot de fréquence se place **après** le verbe.","type":"ordre","items":[{"id":"a","texte":"never"},{"id":"b","texte":"is"},{"id":"c","texte":"Kirsty"},{"id":"d","texte":"late for school."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Il est **8 h moins le quart** (*quarter to eight*) : **she catches the school bus**."},{"cle":{"type":"zone","ids":["m38","m56","m62","m83"]},"explication":"**always** (toujours), **usually** (d’habitude), **never** (jamais), **sometimes** (parfois) : ils se placent **avant** le verbe, mais **après** *be* (*I am never late*)."},{"cle":{"type":"trous","trous":[["gets"],["feeds"],["catches"]]},"affichage":"gets · feeds · catches","explication":"Kirsty **gets** up, she **feeds** the sheep and she **catches** the bus : **-s** à la 3e personne du singulier, **-es** après -ch."},{"cle":{"type":"choix","ids":["d"]},"explication":"Kirsty prend le bus, elle ne marche pas : **No, she doesn’t.** La réponse courte reprend l’auxiliaire *does*, à la forme négative."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"**Kirsty is never late for school.** Avec *be*, *never* se met **après** le verbe ; avec les autres verbes, il se met **avant** (*she never eats…*)."}]$ex$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un samedi à Hyde Park","competence":"observer-schema","situation":"Samedi après-midi, à Hyde Park, le grand parc du centre de Londres. Assis sur un banc, Harry dessine ce qu’il voit pour sa correspondante française.","documents":[{"id":"parc","type":"schema","titre":"Le dessin de Harry","largeur":320,"hauteur":250,"elements":[{"forme":"rect","x":10,"y":10,"l":300,"h":230,"arrondi":14,"teinte":"vert","motif":"clair"},{"forme":"ellipse","cx":235,"cy":58,"rx":66,"ry":34,"teinte":"bleu","motif":"clair"},{"forme":"texte","x":235,"y":106,"texte":"The Serpentine","taille":"petit","italique":true,"teinte":"bleu"},{"forme":"polygone","points":[[10,150],[310,126],[310,150],[10,174]],"teinte":"sable","motif":"plein"},{"forme":"emoji","x":38,"y":42,"emoji":"🌳","taille":30},{"forme":"emoji","x":88,"y":34,"emoji":"🌳","taille":26},{"forme":"emoji","x":138,"y":50,"emoji":"🌳","taille":28},{"forme":"emoji","id":"z1","zone":true,"x":222,"y":58,"emoji":"🦆","taille":24},{"forme":"emoji","id":"z2","zone":true,"x":90,"y":146,"emoji":"🚴","taille":32},{"forme":"texte","x":90,"y":190,"texte":"Sam","taille":"petit","gras":true},{"forme":"emoji","id":"z3","zone":true,"x":200,"y":132,"emoji":"🏃","taille":30},{"forme":"emoji","id":"z4","zone":true,"x":240,"y":138,"emoji":"🐕","taille":24},{"forme":"texte","x":200,"y":170,"texte":"Leo","taille":"petit","gras":true},{"forme":"emoji","id":"z5","zone":true,"x":55,"y":206,"emoji":"💃","taille":30},{"forme":"texte","x":55,"y":234,"texte":"Ella","taille":"petit","gras":true},{"forme":"emoji","id":"z6","zone":true,"x":160,"y":206,"emoji":"🤹","taille":30},{"forme":"texte","x":160,"y":234,"texte":"Max","taille":"petit","gras":true},{"forme":"emoji","id":"z7","zone":true,"x":265,"y":206,"emoji":"🤳","taille":30},{"forme":"texte","x":265,"y":234,"texte":"Mia","taille":"petit","gras":true}]}],"questions":[{"enonce":"Touche la personne qui *is riding a bike*.","aide":"*a bike*, c’est un vélo. Cherche sur le chemin.","type":"zone","document":"parc","multiple":false},{"enonce":"Touche l’animal qui *is swimming*.","aide":"Il y a deux animaux dans le parc. Lequel est dans l’eau ?","type":"zone","document":"parc","multiple":false},{"enonce":"Harry décrit la scène. Complète avec la bonne forme de BE : *am*, *is* ou *are*.","aide":"Leo et son chien, c’est *they* ; Max, c’est *he* ; et avec *I*, BE devient… ?","type":"trous","segments":["Look! Leo and his dog ",0," running and Max ",1," juggling. And me? I ",2," sitting on a bench!"],"banque":["be","am","is","are"]},{"enonce":"What is **Mia** doing?","aide":"Trouve le prénom Mia sous un personnage : que tient-elle à la main ?","type":"choix","options":[{"id":"a","texte":"She is juggling."},{"id":"b","texte":"She is taking a photo."},{"id":"c","texte":"She is swimming."},{"id":"d","texte":"She is dancing."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **Sam** : *Sam is riding a bike*, il est en train de faire du vélo."},{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est **le canard** : *the duck is swimming* sur le lac. Le chien, lui, *is running* avec Leo."},{"cle":{"type":"trous","trous":[["are"],["is"],["am"]]},"affichage":"are · is · am","explication":"Leo and his dog **are** running (*they*), Max **is** juggling (*he*), I **am** sitting : BE s’accorde avec le sujet, puis vient le verbe en -ing."},{"cle":{"type":"choix","ids":["b"]},"explication":"Mia tient son téléphone : **she is taking a photo** (elle prend une photo). C’est Ella qui danse et Max qui jongle."}]$ex$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Personne n’est libre dimanche !","competence":"manier-langue","situation":"Dimanche, 11 heures. Maddie veut aller au cinéma. Elle écrit sur le groupe de sa famille… mais tout le monde est occupé !","documents":[{"id":"groupe","type":"dialogue","modele":"sms","titre":"Le groupe « The Browns »","participants":[{"nom":"Maddie","emoji":"👧","cote":"droite"},{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Dad","emoji":"👨","cote":"gauche"},{"nom":"Ollie","emoji":"👦","cote":"gauche"}],"repliques":[{"qui":"Maddie","texte":"Hi everyone! Who wants to come to the cinema with me? 🍿"},{"qui":"Mum","texte":"Sorry, darling, I’m making a cake for Granny 🎂"},{"qui":"Dad","texte":"I’m in the garden. I’m cutting the grass 🌱"},{"qui":"Ollie","texte":"Can’t! We’re swimming at the leisure centre with the team 🏊"},{"qui":"Maddie","texte":"OK… I understand 😒 I’m writing to Zoe, then!"}]}],"questions":[{"enonce":"Touche les **deux** verbes en -ING qui ont **perdu leur e** final.","aide":"Pense à la base verbale de chaque verbe en -ING : lesquelles se terminent par un -e muet ?","type":"zone","document":"groupe","multiple":true},{"enonce":"Touche maintenant les **deux** verbes en -ING dont la consonne finale a été **doublée**.","aide":"Ce sont des verbes courts qui se terminent par consonne + voyelle + consonne.","type":"zone","document":"groupe","multiple":true},{"enonce":"Maddie écrit « I **understand** », et pas « I am understanding ». Pourquoi ?","aide":"*understand* dit ce qu’on pense, pas ce qu’on fait. Que dit le cours de ces verbes-là ?","type":"choix","options":[{"id":"a","texte":"Parce que *understand* est un verbe d’état : il refuse la forme en -ING"},{"id":"b","texte":"Parce que *understand* est un verbe irrégulier"},{"id":"c","texte":"Parce qu’elle parle d’une habitude de tous les jours"},{"id":"d","texte":"Parce que sa phrase est à la forme négative"}],"multiple":false},{"enonce":"Zoe répond à Maddie. Conjugue les verbes au présent en BE + -ING.","aide":"D’abord la forme de BE qui va avec *I*, puis avec *we*. Ensuite, applique les règles d’orthographe du -ing à *sit* et à *drive*.","type":"trous","segments":["Sorry, Maddie! I ",0," (sit) in the car with my parents. We ",1," (drive) to Wales!"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14","m41"]},"explication":"**making** (*make*) et **writing** (*write*) : le **e muet** tombe devant -ing."},{"cle":{"type":"zone","ids":["m24","m29"]},"explication":"**cutting** (*cut*) et **swimming** (*swim*) : verbes courts en consonne-voyelle-consonne, on **double** la dernière consonne."},{"cle":{"type":"choix","ids":["a"]},"explication":"*understand* est un **verbe d’état**, comme *know*, *like* ou *want* : on ne le met **pas** à la forme en -ING, même quand on parle de maintenant."},{"cle":{"type":"trous","trous":[["am sitting","m sitting"],["are driving","re driving"]]},"affichage":"am sitting · are driving","explication":"I **am sitting** (*sit* : on double le t) · We **are driving** (*drive* : le e muet tombe). Les contractions *I’m sitting* et *we’re driving* sont justes aussi."}]$ex$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une semaine pas comme les autres","competence":"comprendre-langue","situation":"Sophie, 12 ans, habite à Manchester. Pendant les vacances, elle passe une semaine chez sa tante Rose, au bord de la mer, en Cornouailles. Elle écrit à son amie Lina, puis sa mère lui envoie des messages.","documents":[{"id":"email","type":"texte","genre":"lettre","titre":"Sophie’s email to Lina","source":"Texte imaginé pour l’exercice.","blocs":["Hi Lina! Guess where I am? In Cornwall! I’m staying with my Aunt Rose for the holidays.","At home, I get up at seven every day. Here, I’m getting up at nine! Aunt Rose has got a little café near the beach. She makes the best scones in England 😋 At the moment, we’re painting the café: it’s blue and yellow now!","I love Cornwall. Write soon! Sophie xx"]},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de maman","participants":[{"nom":"Mum","emoji":"👩","cote":"gauche"},{"nom":"Sophie","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Mum","texte":"Hello sweetie! What are you doing?"},{"qui":"Sophie","texte":"I’m walking on the beach with Aunt Rose’s dog 🐕"},{"qui":"Mum","texte":"Lovely! Is it raining?"},{"qui":"Sophie","texte":"No, it isn’t. The sun is shining ☀️"},{"qui":"Mum","texte":"Do you want to come home on Saturday?"},{"qui":"Sophie","texte":"No! I want to stay here 😄"}]}],"questions":[{"enonce":"Pourquoi Sophie écrit-elle « I **get up** at seven » mais « I**’m getting up** at nine » ?","aide":"Relis le paragraphe 2 : où Sophie se lève-t-elle à 7 h ? Et où se lève-t-elle à 9 h ?","type":"choix","options":[{"id":"a","texte":"Les deux phrases veulent dire exactement la même chose"},{"id":"b","texte":"7 h, c’est le passé ; 9 h, c’est le futur"},{"id":"c","texte":"Elle se lève à 9 h tous les jours de l’année"},{"id":"d","texte":"7 h, c’est son habitude à la maison ; 9 h, c’est temporaire, juste pendant les vacances"}],"multiple":false},{"enonce":"Range ces phrases des deux documents selon ce qu’elles expriment.","aide":"Pour chaque phrase, demande-toi : est-ce vrai tout le temps, ou seulement maintenant, cette semaine ?","type":"categories","categories":[{"id":"c0","texte":"Habitude, goût ou vérité : présent simple"},{"id":"c1","texte":"En ce moment ou temporaire : BE + -ING"}],"items":[{"id":"i0","texte":"The sun is shining."},{"id":"i1","texte":"At home, I get up at seven every day."},{"id":"i2","texte":"I’m staying with my Aunt Rose."},{"id":"i3","texte":"She makes the best scones in England."},{"id":"i4","texte":"I love Cornwall."},{"id":"i5","texte":"We’re painting the café."}]},{"enonce":"Dans l’e-mail, touche le verbe qui exprime un **goût** : il refuse la forme en -ING.","aide":"C’est un verbe qui dit ce que Sophie ressent pour les Cornouailles.","type":"zone","document":"email","multiple":false},{"enonce":"Maman écrit ensuite : « ___ Aunt Rose working in the café today? » Quel mot manque ?","aide":"Au présent en BE + -ING, la question se fait sans DO : c’est BE qui passe devant le sujet.","type":"texte","placeholder":"… Aunt Rose working?"},{"enonce":"Sophie envoie une photo à Lina. Complète sa légende en conjuguant les verbes au présent en BE + -ING.","aide":"*is* + verbe en -ing. *run* est un verbe court en consonne-voyelle-consonne ; *dance* se termine par un e muet.","type":"trous","segments":["Look! The dog ",0," (run) after a seagull and Aunt Rose ",1," (dance) on the sand!"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"**At home**, d’habitude → présent simple : *I get up*. **Here**, pendant les vacances seulement → action **temporaire** : *I’m getting up*."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"Présent simple : les scones (**toujours** délicieux), *I love* (un **goût**), *every day* (une **habitude**). BE + -ING : le séjour chez Rose, la peinture et le soleil, **en ce moment**."},{"cle":{"type":"zone","ids":["m62"]},"explication":"**love** est un verbe d’état : on écrit *I love Cornwall*, jamais « I am loving Cornwall »."},{"cle":{"type":"texte","acceptes":["is"]},"affichage":"Is","explication":"**Is** Aunt Rose working…? C’est **BE** (*is*, car Aunt Rose = *she*) qui passe devant le sujet, pas *do*."},{"cle":{"type":"trous","trous":[["is running","s running"],["is dancing","s dancing"]]},"affichage":"is running · is dancing","explication":"The dog **is running** (on double le n) and Aunt Rose **is dancing** (le e muet tombe)."}]$ex$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le nouveau de la 6e C","competence":"analyser-document","situation":"Hugo vient d’arriver en 6e C, en plein mois de novembre. Le soir même, sur le groupe de discussion de la classe, on parle de lui… Lis la conversation.","documents":[{"id":"sms","type":"dialogue","modele":"sms","titre":"Le groupe « 6e C 🏀 »","source":"Conversation imaginée pour l’exercice.","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Enzo","emoji":"👦","cote":"gauche"},{"nom":"Maëlys","emoji":"🧒","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Vous avez vu le nouveau ? Il a un truc derrière l’oreille 👂"},{"qui":"Enzo","texte":"Mdr on l’appelle Bluetooth 😂😂"},{"qui":"Maëlys","texte":"C’est un appareil auditif. Il entend moins bien, c’est tout."},{"qui":"Enzo","texte":"De toute façon, les nouveaux sont tous bizarres 🙄"},{"qui":"Lina","texte":"Tu le connais même pas 😅"},{"qui":"Maëlys","texte":"Demain, je lui propose de manger avec nous à la cantine 🙂"}]}],"questions":[{"enonce":"Enzo invente un **surnom** pour se moquer de Hugo. Touche-le dans la conversation.","aide":"Un surnom remplace le prénom de quelqu’un. Cherche ce que « on l’appelle ».","type":"zone","document":"sms","multiple":false},{"enonce":"Enzo écrit : « les nouveaux sont tous bizarres ». Comment appelle-t-on une idée toute faite sur **tout un groupe** de personnes ?","aide":"Enzo parle de « tous » les nouveaux… sans en connaître un seul.","type":"choix","options":[{"id":"a","texte":"Un stéréotype"},{"id":"b","texte":"Un compliment"},{"id":"c","texte":"Une preuve"},{"id":"d","texte":"Une règle du collège"}],"multiple":false},{"enonce":"Range chaque message de la conversation.","aide":"Un message respectueux ne rabaisse pas Hugo : il explique sa différence, le défend ou l’accueille.","type":"categories","categories":[{"id":"c0","texte":"Respecte Hugo"},{"id":"c1","texte":"Ne respecte pas Hugo"}],"items":[{"id":"i0","texte":"« C’est un appareil auditif. Il entend moins bien, c’est tout. »"},{"id":"i1","texte":"« On l’appelle Bluetooth 😂 »"},{"id":"i2","texte":"« Les nouveaux sont tous bizarres »"},{"id":"i3","texte":"« Je lui propose de manger avec nous »"},{"id":"i4","texte":"« Tu le connais même pas »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m16"]},"explication":"**Bluetooth** : ce surnom se moque d’un appareil auditif, donc d’une différence liée à la santé. Donner un surnom sans l’accord de la personne, même « pour rire », c’est manquer de respect."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est un **stéréotype** : une idée toute faite sur un groupe, qui se répand sans preuve. Lina le lui fait remarquer : Enzo ne connaît même pas Hugo."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Le surnom et le stéréotype **rabaissent** Hugo. Maëlys et Lina, elles, expliquent sa différence, rappellent qu’on ne le connaît pas et l’accueillent : le respect, ce sont des **gestes qui se voient**."}]$ex$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Discrimination ou pas ? La loi tranche","competence":"raisonner","situation":"Nour et Théo ont entendu parler de cinq situations cette semaine. Certaines sont-elles des **discriminations** ? Pour le savoir, ils lisent ce que dit la loi.","documents":[{"id":"loi","type":"texte","genre":"source","titre":"Ce que dit le Code pénal","source":"D’après le Code pénal, articles 225-1 et 225-2 (extraits simplifiés).","blocs":["**Article 225-1.** Constitue une discrimination toute distinction faite entre les personnes à cause de leur origine, de leur sexe, de leur situation de famille, de leur apparence physique, de leur nom de famille, de leur lieu de résidence, de leur état de santé, de leur handicap, de leur âge, de leurs opinions politiques ou de leur religion…","**Article 225-2.** La discrimination est punie de trois ans d’emprisonnement et de 45 000 euros d’amende lorsqu’elle consiste notamment à refuser un bien ou un service, ou à refuser d’embaucher une personne."]},{"id":"cas","type":"texte","genre":"recit","titre":"Cinq situations entendues cette semaine","source":"Situations imaginées pour l’exercice.","blocs":["**A.** Le club de foot de la ville refuse l’inscription de Jade : « Le foot, ce n’est pas pour les filles. »","**B.** La boulangerie ne sert pas Karim, arrivé dix minutes après l’heure de fermeture.","**C.** Un restaurant refuse d’installer M. Petit, qui se déplace en fauteuil roulant, alors que la salle est de plain-pied : « Ça gênerait les autres clients. »","**D.** Le professeur de musique met 8 sur 20 à Lucas, qui n’avait pas appris sa partition.","**E.** Une agence refuse de louer un appartement à Mme Diallo à cause de son nom de famille."]}],"questions":[{"enonce":"Situation A : dans l’article 225-1, touche le mot qui correspond à la raison du refus fait à Jade.","aide":"Jade est refusée parce qu’elle est une fille. Quel critère de la liste est-ce ?","type":"zone","document":"loi","multiple":false},{"enonce":"Range les cinq situations du Doc 2.","aide":"Pour chaque situation, demande-toi : la personne est-elle traitée moins bien à cause d’un critère de la liste (sexe, handicap, nom…), ou pour une raison valable pour tout le monde ?","type":"categories","categories":[{"id":"c0","texte":"Discrimination interdite par la loi"},{"id":"c1","texte":"Pas une discrimination"}],"items":[{"id":"i0","texte":"A. Jade refusée au club de foot"},{"id":"i1","texte":"B. Karim pas servi après la fermeture"},{"id":"i2","texte":"D. Lucas noté 8 sur 20"},{"id":"i3","texte":"C. M. Petit refusé au restaurant"},{"id":"i4","texte":"E. Mme Diallo refusée à cause de son nom"}]},{"enonce":"D’après l’article 225-2, combien d’années de prison le restaurant qui refuse M. Petit risque-t-il **au maximum** ?","aide":"Refuser d’installer un client, c’est refuser un service. Relis l’article 225-2.","type":"nombre","unite":"ans"},{"enonce":"Le patron du restaurant se défend : « Je n’ai rien contre les personnes handicapées, c’est pour les autres clients. » Qu’en dit la loi ?","aide":"Relis la définition : la loi parle de ce qu’on FAIT (une distinction), pas de ce qu’on pense.","type":"choix","options":[{"id":"a","texte":"Ce n’est pas une discrimination, puisqu’il dit n’avoir rien contre lui"},{"id":"b","texte":"C’est une discrimination : il a traité M. Petit moins bien à cause de son handicap"},{"id":"c","texte":"C’est autorisé si la plupart des autres clients sont d’accord"},{"id":"d","texte":"C’est autorisé, car un restaurant choisit librement tous ses clients"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m18"]},"explication":"Le **sexe** : refuser Jade parce qu’elle est une fille, c’est la traiter moins bien à cause de son sexe. C’est une discrimination."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"A (le **sexe**), C (le **handicap**) et E (le **nom de famille**) sont des discriminations. Karim et Lucas ne sont pas traités moins bien pour ce qu’ils sont, mais pour une raison valable pour tous : l’heure de fermeture, une partition non apprise."},{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 ans","explication":"Jusqu’à **3 ans** d’emprisonnement et 45 000 euros d’amende : la discrimination n’est pas seulement impolie, c’est un **délit**."},{"cle":{"type":"choix","ids":["b"]},"explication":"**C’est une discrimination** : la loi juge l’acte — traiter quelqu’un moins bien à cause de son handicap —, pas les intentions. Le confort des « autres clients » n’est pas une excuse."}]$ex$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Égaux en dignité, même en plein débat","competence":"argumenter","situation":"En 6e D, le débat du jour porte sur une question : « Faut-il des devoirs le week-end ? ». Le ton monte… Lis le compte rendu écrit par la secrétaire de séance, puis un texte de 1948.","documents":[{"id":"debat","type":"texte","genre":"recit","titre":"Compte rendu du débat","source":"Compte rendu imaginé pour l’exercice.","blocs":["Iris ouvre le débat : elle est **pour** les devoirs le week-end, « parce que ça fait réviser ». Nour lève la main et répond qu’elle est **contre** : le samedi, elle aide ses parents au marché.","Kylian coupe la parole à Nour : « Toi, t’as de mauvaises notes, ton avis ne compte pas. » Quelques élèves rient.","Iris intervient : « Je ne suis pas d’accord avec Nour, mais je veux entendre ses arguments jusqu’au bout. »","À la fin de l’heure, Kylian va voir Nour : « J’ai été nul tout à l’heure. Excuse-moi. » Nour accepte ses excuses."]},{"id":"dudh","type":"texte","genre":"source","titre":"Article 1","auteur":"Déclaration universelle des droits de l’homme (10 décembre 1948)","blocs":["Tous les êtres humains naissent libres et égaux en dignité et en droits. Ils sont doués de raison et de conscience et doivent agir les uns envers les autres dans un esprit de fraternité."]}],"questions":[{"enonce":"Pour Kylian, l’avis de Nour ne vaut rien. Sur quoi s’appuie-t-il ? Touche le mot dans le Doc 1.","aide":"Relis le paragraphe 2 : Kylian reproche quelque chose à Nour pour lui refuser la parole.","type":"zone","document":"debat","multiple":false},{"enonce":"Dans le Doc 2, touche le mot qui montre que Kylian a tort : chacun a la même valeur, quelles que soient ses notes.","aide":"Cherche ce en quoi tous les êtres humains sont « égaux », en plus des droits.","type":"zone","document":"dudh","multiple":false},{"enonce":"Iris n’est pas d’accord avec Nour. La respecte-t-elle quand même ?","aide":"Relis ce que dit Iris au paragraphe 3.","type":"choix","options":[{"id":"a","texte":"Non : pour la respecter, elle aurait dû se taire pendant le débat"},{"id":"b","texte":"On ne peut pas le savoir en lisant le compte rendu"},{"id":"c","texte":"Oui : respecter, ce n’est pas être d’accord, c’est écouter sans rabaisser"},{"id":"d","texte":"Non : pour respecter quelqu’un, il faut être d’accord avec lui"}],"multiple":false},{"enonce":"Range les gestes du débat.","aide":"Les gestes du respect : écouter sans couper, ne pas se moquer, s’excuser quand on a blessé.","type":"categories","categories":[{"id":"c0","texte":"Geste de respect"},{"id":"c1","texte":"Manque de respect"}],"items":[{"id":"i0","texte":"Nour lève la main pour parler"},{"id":"i1","texte":"Iris veut entendre les arguments jusqu’au bout"},{"id":"i2","texte":"Kylian juge l’avis de Nour d’après ses notes"},{"id":"i3","texte":"Des élèves rient de Nour"},{"id":"i4","texte":"Kylian coupe la parole à Nour"},{"id":"i5","texte":"Kylian s’excuse auprès de Nour"}]},{"enonce":"Complète la conclusion que la classe écrit au tableau.","aide":"Le premier mot vient du Doc 2 ; le second, de ce que Kylian reprochait à Nour.","type":"trous","segments":["Tous les êtres humains sont égaux en ",0,". Elle ne se gagne pas avec de bonnes ",1," : c’est pourquoi l’avis de Nour compte autant que celui de Kylian."],"banque":["notes","popularité","dignité","argent","force"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m45"]},"explication":"Sur ses **notes**. Or la dignité d’une personne ne dépend ni de ses notes, ni de l’argent, ni de l’apparence : elle ne se mérite pas et ne se perd pas."},{"cle":{"type":"zone","ids":["m9"]},"explication":"La **dignité** : tous les êtres humains sont égaux en dignité. L’avis de Nour compte donc autant que celui des autres, bonnes ou mauvaises notes."},{"cle":{"type":"choix","ids":["c"]},"explication":"**Oui** : Iris garde son avis, mais veut entendre Nour jusqu’au bout. Respecter quelqu’un, ce n’est pas être d’accord avec lui : c’est refuser de le rabaisser."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1","i5":"c0"}},"explication":"Lever la main, écouter jusqu’au bout et **s’excuser** sont des gestes de respect. Couper la parole, rire de quelqu’un et le juger d’après ses notes, non. Kylian finit par réparer : s’excuser, c’est aussi du respect."},{"cle":{"type":"trous","trous":[["dignite"],["notes"]]},"affichage":"dignité · notes","explication":"Égaux en **dignité** : elle ne se gagne pas avec de bonnes **notes** et ne se perd pas avec de mauvaises. C’est le fondement de tous les droits."}]$ex$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une dispute qui commence mal","competence":"analyser-texte","situation":"Le rideau se lève. Deux personnages entrent en scène… et ils ne sont pas d’accord du tout. Lis le début de la pièce de Molière.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Acte I, scène 1","auteur":"D’après Molière, Le Médecin malgré lui (1666)","blocs":[{"didascalie":"Sganarelle et Martine paraissent sur le théâtre en se querellant."},{"personnage":"Sganarelle","replique":"Non, je te dis que je n’en veux rien faire, et que c’est à moi de parler et d’être le maître."},{"personnage":"Martine","replique":"Et je te dis, moi, que je veux que tu vives à ma fantaisie, et que je ne me suis point mariée avec toi pour souffrir tes fredaines."},{"personnage":"Sganarelle","replique":"Ô la grande fatigue que d’avoir une femme ! Et qu’Aristote a bien raison, quand il dit qu’une femme est pire qu’un démon !"},{"personnage":"Martine","replique":"Voyez un peu l’habile homme, avec son benêt d’Aristote !"},{"personnage":"Sganarelle","replique":"Oui, habile homme : trouve-moi un faiseur de fagots qui sache, comme moi, raisonner des choses, qui ait servi six ans un fameux médecin."}]}],"questions":[{"enonce":"Comment appelle-t-on la phrase en italique, au début de la scène, qui dit comment les acteurs entrent en scène ?","aide":"Ce mot désigne les indications de mise en scène, souvent écrites en italique.","type":"choix","options":[{"id":"a","texte":"Une didascalie"},{"id":"b","texte":"Une tirade"},{"id":"c","texte":"Une réplique"},{"id":"d","texte":"Un aparté"}],"multiple":false},{"enonce":"Quel est le vrai métier de Sganarelle ? Touche **les trois mots** qui le disent dans sa dernière réplique.","aide":"Un fagot est un paquet de petites branches. Sganarelle coupe du bois.","type":"zone","document":"scene","multiple":true},{"enonce":"Martine répond : « Voyez un peu l’habile homme ! » Que veut-elle dire ?","aide":"Elle ajoute juste après : « avec son benêt d’Aristote ». Un benêt, c’est un sot.","type":"choix","options":[{"id":"a","texte":"Elle a peur de lui"},{"id":"b","texte":"Elle se moque de lui : elle pense le contraire"},{"id":"c","texte":"Elle l’admire sincèrement"},{"id":"d","texte":"Elle veut qu’il devienne médecin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"C’est une **didascalie** : elle n’est pas dite par les acteurs, elle leur indique comment jouer."},{"cle":{"type":"zone","ids":["m104","m105","m106"]},"explication":"Sganarelle est un **faiseur de fagots**, un bûcheron. Il se vante pourtant d’avoir « servi un fameux médecin » : c’est ce qui va lancer toute l’histoire."},{"cle":{"type":"choix","ids":["b"]},"explication":"Martine est **ironique** : elle dit « habile homme » (homme intelligent) pour se moquer de lui."}]$ex$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le faux latin du faux médecin","competence":"analyser-texte","situation":"Sganarelle se fait passer pour un grand médecin. Géronte lui demande pourquoi sa fille Lucinde ne parle plus. Sganarelle se lance dans une explication très… savante.","documents":[{"id":"consultation","type":"texte","genre":"theatre","titre":"Acte II, scène 4 (extrait)","auteur":"D’après Molière, Le Médecin malgré lui (1666)","blocs":[{"personnage":"Sganarelle","replique":"Or ces vapeurs, venant à passer du côté gauche, où est le foie, au côté droit, où est le cœur, il se trouve que le poumon, que nous appelons en latin armyan, ayant communication avec le cerveau, que nous nommons en grec nasmus, par le moyen de la veine cave, que nous appelons en hébreu cubile… Et voilà justement ce qui fait que votre fille est muette."},{"personnage":"Géronte","replique":"On ne peut pas mieux raisonner, sans doute. Il n’y a qu’une seule chose qui m’a choqué : c’est l’endroit du foie et du cœur. Il me semble que le cœur est du côté gauche, et le foie du côté droit."},{"personnage":"Sganarelle","replique":"Oui, cela était autrefois ainsi ; mais nous avons changé tout cela, et nous faisons maintenant la médecine d’une méthode toute nouvelle."}]}],"questions":[{"enonce":"Sganarelle invente de faux mots savants. Touche **les trois mots inventés** qu’il fait passer pour du latin, du grec et de l’hébreu.","aide":"Cherche ce qui suit « en latin », « en grec » et « en hébreu ».","type":"zone","document":"consultation","multiple":true},{"enonce":"Quelle erreur Géronte remarque-t-il ?","aide":"Relis la réplique de Géronte : il parle de « l’endroit du foie et du cœur ».","type":"choix","options":[{"id":"a","texte":"Sganarelle a inversé la place du cœur et celle du foie"},{"id":"b","texte":"Sganarelle parle trop vite"},{"id":"c","texte":"Sganarelle s’est trompé sur le nom de sa fille"},{"id":"d","texte":"Sganarelle a oublié de parler du cerveau"}],"multiple":false},{"enonce":"Comment Sganarelle se tire-t-il d’affaire ?","aide":"Relis sa dernière réplique : « nous avons changé tout cela ».","type":"choix","options":[{"id":"a","texte":"Il avoue qu’il n’est pas médecin"},{"id":"b","texte":"Il prétend que la médecine a changé et que tout a été déplacé"},{"id":"c","texte":"Il donne un coup de bâton à Géronte"},{"id":"d","texte":"Il s’enfuit"}],"multiple":false},{"enonce":"Range chaque moment de la pièce dans la bonne forme de comique.","aide":"Les gestes se voient, les mots s’entendent, la situation vient d’un malentendu.","type":"categories","categories":[{"id":"c0","texte":"Comique de gestes"},{"id":"c1","texte":"Comique de mots"},{"id":"c2","texte":"Comique de situation"}],"items":[{"id":"i0","texte":"« Et voilà justement ce qui fait que votre fille est muette »"},{"id":"i1","texte":"Sganarelle reçoit des coups de bâton"},{"id":"i2","texte":"Sganarelle parle un latin inventé"},{"id":"i3","texte":"Géronte croit parler à un vrai médecin"},{"id":"i4","texte":"Sganarelle fait des grimaces et des courbettes"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31","m42","m55"]},"explication":"**Armyan**, **nasmus** et **cubile** ne veulent rien dire : c’est du « latin de cuisine ». Géronte ne comprend rien, mais il est impressionné."},{"cle":{"type":"choix","ids":["a"]},"explication":"Sganarelle a mis le foie à gauche et le cœur à droite : c’est **l’inverse** de la réalité."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec un aplomb incroyable, il répond que la médecine a une « méthode toute nouvelle » : **on a changé tout cela**. C’est le cœur du comique : le mensonge énorme, dit avec assurance."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c2","i4":"c0"}},"explication":"Coups et grimaces : **comique de gestes**. Faux latin et formules savantes : **comique de mots**. Géronte trompé par un faux médecin : **comique de situation** (un quiproquo)."}]$ex$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une soirée au théâtre","competence":"analyser-document","situation":"La compagnie du collège monte *Le Médecin malgré lui* pour la fête de fin d’année. Aide la troupe à préparer le programme du spectacle.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"L’affiche du spectacle","entete":"Le Médecin malgré lui","sousTitre":"Une comédie de Molière, créée en 1666","emoji":"🎭","teinte":"rose","lignes":[{"texte":"Comédie en **trois actes**"},{"texte":"Par la troupe des 6e du collège"},{"texte":"Vendredi 20 juin à 18 h, salle polyvalente"},{"texte":"Durée :","valeur":"1 h 15"}],"pied":"Entrée libre · Rires garantis"},{"id":"plan","type":"texte","genre":"theatre","titre":"Martine révèle son plan (acte I, scène 4)","auteur":"D’après Molière, Le Médecin malgré lui (1666)","blocs":[{"didascalie":"Deux domestiques, Valère et Lucas, cherchent un médecin pour la fille de leur maître. Martine a une idée pour se venger de son mari."},{"personnage":"Martine","replique":"C’est un homme extraordinaire, qui se plaît à cacher son savoir. Il ne dira jamais qu’il est médecin, à moins que vous ne preniez chacun un bâton et ne le réduisiez, à force de coups, à vous avouer à la fin ce qu’il vous cachera d’abord."},{"personnage":"Valère","replique":"Voilà une étrange folie !"},{"personnage":"Martine","replique":"Il est vrai ; mais, après cela, vous verrez qu’il fait des merveilles."}]}],"questions":[{"enonce":"D’après l’affiche, combien d’années se sont écoulées entre la création de la pièce et l’année **2026** ?","aide":"Fais la soustraction : 2026 − 1666.","type":"nombre","unite":"ans"},{"enonce":"Selon Martine, avec quoi faut-il frapper Sganarelle pour qu’il « avoue » être médecin ? Touche le mot dans le Doc 2.","aide":"C’est un morceau de bois qu’on tient à la main.","type":"zone","document":"plan","multiple":false},{"enonce":"Pour le programme, remets dans l’ordre ce qui arrive à Sganarelle.","aide":"Tout part d’une dispute de couple, et le Doc 2 montre la vengeance qui se prépare.","type":"ordre","items":[{"id":"a","texte":"Martine le fait passer pour un médecin."},{"id":"b","texte":"Il se prend au jeu du faux médecin."},{"id":"c","texte":"Il bat sa femme Martine."},{"id":"d","texte":"On le frappe jusqu’à ce qu’il « avoue »."}]},{"enonce":"Le programme contient un petit lexique du théâtre. Relie chaque mot à sa définition.","aide":"Commence par ceux que tu es sûr de connaître : il en restera moins à relier.","type":"association","gauche":[{"id":"g0","texte":"Une réplique"},{"id":"g1","texte":"Une tirade"},{"id":"g2","texte":"Un monologue"},{"id":"g3","texte":"Un aparté"},{"id":"g4","texte":"Une didascalie"}],"droite":[{"id":"d0","texte":"Ce que dit un personnage"},{"id":"d1","texte":"Une phrase que les autres personnages n’entendent pas"},{"id":"d2","texte":"Un personnage seul en scène qui parle"},{"id":"d3","texte":"Une indication de mise en scène"},{"id":"d4","texte":"Une longue réplique"}]},{"enonce":"Complète la présentation de la pièce pour le programme.","aide":"Le premier mot est dans le titre de la pièce ; le second désigne le fait de tout croire.","type":"trous","segments":["Derrière le rire, Molière se moque des ",0," de son temps, de leur jargon et de leur assurance, mais aussi de la ",1," de ceux qui croient tout ce qu’on leur dit."],"banque":["politesse","colère","crédulité","avocats","médecins","rois"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":360,"tolerance":0},"affichage":"360 ans","explication":"2026 − 1666 = **360 ans** : la pièce fait encore rire, plus de trois siècles et demi après sa création."},{"cle":{"type":"zone","ids":["m52"]},"explication":"Un **bâton** : les coups de bâton sont un grand classique de la farce. Martine se venge ainsi des coups que son mari lui a donnés."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"La dispute → la vengeance de Martine → les coups de bâton → Sganarelle devient médecin. Tout part d’une **vengeance**."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g2":"d2","g4":"d3","g1":"d4"}},"explication":"Réplique, tirade, monologue, aparté, didascalie : ce sont les cinq mots du **vocabulaire du théâtre** à connaître."},{"cle":{"type":"trous","trous":[["medecins"],["credulite"]]},"affichage":"médecins · crédulité","explication":"Molière dénonce les **médecins** qui cachent leur ignorance derrière des mots savants, et la **crédulité** de leurs patients."}]$ex$::jsonb),
  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les géants des mers","competence":"lire-carte","situation":"Ton t-shirt, ton téléphone, ta console : ils ont très probablement voyagé en bateau, dans un **conteneur**. Découvre les ports où ces boîtes géantes arrivent par millions.","documents":[{"id":"carte","type":"carte","titre":"Trois très grands ports du monde","fond":"monde","cadrage":[-20,-12,140,62],"lieux":[{"id":"z1","lieu":"shanghai","symbole":"lettre","lettre":"A","teinte":"bleu"},{"id":"z2","lieu":"singapour","symbole":"lettre","lettre":"B","teinte":"bleu"},{"id":"z3","lieu":"rotterdam","symbole":"lettre","lettre":"C","teinte":"bleu"}]},{"id":"trafic","type":"tableau","titre":"Le nombre de conteneurs passés par chaque port en une année","source":"Chiffres arrondis, année 2023.","colonnes":["Port","Pays","Conteneurs (en millions)"],"lignes":[["Shanghai","Chine",49],["Singapour","Singapour",39],["Rotterdam","Pays-Bas",13],["Le Havre","France",3]],"enteteLignes":true}],"questions":[{"enonce":"D’après le Doc 2, quel est le **premier port du monde** ?","aide":"Cherche le plus grand nombre dans la dernière colonne.","type":"choix","options":[{"id":"a","texte":"Shanghai"},{"id":"b","texte":"Singapour"},{"id":"c","texte":"Rotterdam"},{"id":"d","texte":"Le Havre"}],"multiple":false},{"enonce":"Sur la carte, touche le repère qui correspond à **Shanghai**, en Chine.","aide":"La Chine se trouve en Asie, tout à l’est de la carte.","type":"zone","document":"carte","multiple":false},{"enonce":"Sur quel continent se trouve le port de **Rotterdam** ?","aide":"Rotterdam est aux Pays-Bas, le repère C sur la carte.","type":"choix","options":[{"id":"a","texte":"En Asie"},{"id":"b","texte":"En Europe"},{"id":"c","texte":"En Afrique"},{"id":"d","texte":"En Amérique"}],"multiple":false}]}$ex$::jsonb,
