  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Port-Soleil, la ville qui change de taille","competence":"lire-graphique","situation":"Port-Soleil est une petite ville au bord de la mer. Chaque année, entre juillet et août, il s’y passe quelque chose d’étonnant.","documents":[{"id":"population","type":"graphique","forme":"barres","titre":"Le nombre de personnes présentes à Port-Soleil chaque mois","categories":["Janv.","Févr.","Mars","Avr.","Mai","Juin","Juil.","Août","Sept.","Oct.","Nov.","Déc."],"series":[{"nom":"Personnes présentes","valeurs":[7,6,7,9,12,20,38,42,15,8,7,7],"teinte":"turquoise"}],"axeY":{"titre":"Personnes présentes","unite":"en milliers","min":0,"max":45,"pas":5}},{"id":"article","type":"texte","genre":"article","titre":"« Port-Soleil, la ville accordéon »","source":"Article de journal imaginé pour l’exercice.","blocs":["Chaque été, Port-Soleil voit sa population exploser. Campings, résidences secondaires et hôtels affichent complet, et les restaurants embauchent des serveurs, des sauveteurs et des cuisiniers… pour deux mois seulement.","Mais ce succès a un prix. Le long de la plage, les immeubles ont remplacé les dunes : les habitants parlent de bétonisation. En hiver, beaucoup de volets restent fermés et les rues sont vides."]}],"questions":[{"enonce":"Combien de personnes sont présentes à Port-Soleil en **août** ?","aide":"Attention : le graphique compte en **milliers**. 1 millier = 1 000.","type":"nombre","unite":"personnes"},{"enonce":"Touche le mois où il y a **le moins de monde** à Port-Soleil.","aide":"Cherche la barre la plus basse.","type":"zone","document":"population","multiple":false},{"enonce":"Combien de fois plus de personnes y a-t-il en août qu’en février ?","aide":"Divise le nombre d’août par celui de février : 42 ÷ 6.","type":"nombre","unite":"fois plus"},{"enonce":"Dans le Doc 2, touche le mot qui désigne la **construction massive d’immeubles** sur le bord de mer.","aide":"Le mot vient de « béton ».","type":"zone","document":"article","multiple":false},{"enonce":"Comment appelle-t-on les emplois qui n’existent qu’une partie de l’année, comme ceux des serveurs de l’article ?","aide":"Le mot vient de « saison ».","type":"choix","options":[{"id":"a","texte":"Des emplois saisonniers"},{"id":"b","texte":"Des emplois agricoles"},{"id":"c","texte":"Des emplois de bureau"},{"id":"d","texte":"Des emplois industriels"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":42000,"tolerance":0},"affichage":"42 000 personnes","explication":"La barre d’août monte à 42 milliers, soit **42 000 personnes**."},{"cle":{"type":"zone","ids":["k1"]},"explication":"C’est en **février** que la ville est la plus calme : 6 000 personnes."},{"cle":{"type":"nombre","valeur":7,"tolerance":0},"affichage":"7 fois plus","explication":"42 000 ÷ 6 000 = **7** : il y a sept fois plus de monde en août !"},{"cle":{"type":"zone","ids":["m50"]},"explication":"La **bétonisation** : le rivage se couvre de constructions, souvent à la place des dunes et des espaces naturels."},{"cle":{"type":"choix","ids":["a"]},"explication":"Ce sont des **emplois saisonniers** : ils ne durent que le temps de la saison touristique."}]$ex$::jsonb),
  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’immeuble que la mer a rattrapé","competence":"analyser-document","situation":"Sur la côte atlantique, un immeuble construit au bord de la plage a dû être abandonné, puis détruit. Mène l’enquête avec les documents.","documents":[{"id":"signal","type":"texte","genre":"article","titre":"L’histoire du Signal","source":"Texte écrit pour l’exercice, d’après l’histoire vraie de l’immeuble Le Signal à Soulac-sur-Mer (Gironde).","blocs":["À la fin des années 1960, on construit à Soulac-sur-Mer un immeuble de quatre étages, le Signal. Il se trouve alors à environ **200 mètres** de l’océan : les futurs habitants rêvent d’une vue sur la mer.","Mais tempête après tempête, la mer grignote la dune. En **2014**, elle n’est plus qu’à une **vingtaine de mètres** de l’immeuble. Pour la sécurité des habitants, le Signal est évacué.","Resté vide pendant des années, l’immeuble est finalement démoli en **2023**. Il est devenu le symbole du recul du trait de côte."]},{"id":"carte","type":"carte","titre":"Quatre villes du littoral français","fond":"france","fleuves":["garonne","loire","seine"],"lieux":[{"id":"z1","lon":-1.13,"lat":45.51,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"le-havre","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"nice","symbole":"lettre","lettre":"C","teinte":"corail"},{"id":"z4","lieu":"brest","symbole":"lettre","lettre":"D","teinte":"corail"},{"id":"z5","lieu":"bordeaux","nom":"Bordeaux","taille":1}]}],"questions":[{"enonce":"De combien de mètres la mer s’est-elle rapprochée du Signal entre sa construction et 2014 ?","aide":"Au départ, la mer est à 200 m ; en 2014, elle n’est plus qu’à 20 m.","type":"nombre","unite":"m"},{"enonce":"Quel phénomène explique l’histoire du Signal ?","aide":"Relis le paragraphe 2 : la mer « grignote » la dune.","type":"choix","options":[{"id":"a","texte":"La bétonisation"},{"id":"b","texte":"L’agrandissement du port"},{"id":"c","texte":"L’érosion du trait de côte"},{"id":"d","texte":"Une marée noire"}],"multiple":false},{"enonce":"Remets l’histoire du Signal dans l’ordre.","aide":"Aide-toi des dates du Doc 1 : fin des années 1960, 2014, 2023.","type":"ordre","items":[{"id":"a","texte":"Les habitants sont évacués."},{"id":"b","texte":"Les tempêtes grignotent la dune."},{"id":"c","texte":"L’immeuble est construit à 200 m de l’océan."},{"id":"d","texte":"L’immeuble est démoli."}]},{"enonce":"Soulac-sur-Mer se trouve au bord de l’océan Atlantique, au nord de Bordeaux. Touche son repère sur la carte.","aide":"Repère Bordeaux, puis suis la Garonne jusqu’à l’océan.","type":"zone","document":"carte","multiple":false},{"enonce":"Les autres repères de la carte sont aussi des littoraux, mais pas du même type. Range chaque ville.","aide":"Un littoral industrialo-portuaire vit de ses ports et de ses usines ; un littoral touristique, des vacanciers.","type":"categories","categories":[{"id":"c0","texte":"Littoral industrialo-portuaire"},{"id":"c1","texte":"Littoral touristique"}],"items":[{"id":"i0","texte":"Le Havre (B) : un grand port à conteneurs"},{"id":"i1","texte":"Rotterdam : le premier port d’Europe"},{"id":"i2","texte":"Nice (C) : plages, hôtels et aéroport"},{"id":"i3","texte":"Cancún : plages et grands hôtels au Mexique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":180,"tolerance":0},"affichage":"180 m","explication":"200 − 20 = **180 mètres** : la côte a reculé de près de deux terrains de football en moins de cinquante ans."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est l’**érosion** : les vagues et les tempêtes emportent peu à peu le sable, et le trait de côte recule."},{"cle":{"type":"ordre","ids":["c","b","a","d"]},"explication":"Construction (fin des années 1960) → recul de la dune → évacuation (2014) → démolition (2023)."},{"cle":{"type":"zone","ids":["z1"]},"explication":"Soulac-sur-Mer est le repère **A**, à l’embouchure de la Gironde, au bord de l’Atlantique."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1"}},"explication":"Le Havre et Rotterdam sont des **littoraux industrialo-portuaires** ; Nice et Cancún, des **littoraux touristiques**."}]$ex$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le panneau du musée de la Préhistoire","competence":"analyser-document","situation":"En sortie scolaire au musée de la Préhistoire, Nolan a photographié le panneau de la première salle. Mais les lignes ne sont pas dans l’ordre du temps : aide-le à s’y retrouver.","documents":[{"id":"panneau","type":"fiche","modele":"panneau","titre":"Le panneau de la salle 1","entete":"Nos lointains ancêtres","sousTitre":"Musée de la Préhistoire · Salle 1","emoji":"🦴","teinte":"brun","lignes":[{"id":"z1","texte":"**Il y a ≈ 300 000 ans** — *Homo sapiens*, notre espèce, apparaît en Afrique."},{"separateur":true},{"id":"z2","texte":"**Il y a ≈ 2,5 millions d’années** — *Homo habilis* taille les premiers outils en pierre."},{"separateur":true},{"id":"z3","texte":"**Il y a ≈ 40 000 ans** — *Homo neanderthalensis*, l’homme de Néandertal, disparaît d’Europe."},{"separateur":true},{"id":"z4","texte":"**Il y a ≈ 1,9 million d’années** — *Homo erectus* apparaît ; il sera le premier à sortir d’Afrique."}],"pied":"Toutes ces espèces vivaient de chasse et de cueillette."}],"questions":[{"enonce":"Touche la ligne du panneau qui parle des **premiers outils** taillés.","aide":"Cherche le mot « outils » dans les quatre lignes.","type":"zone","document":"panneau","multiple":false},{"enonce":"Range ces quatre événements du **plus ancien** au **plus récent**.","aide":"Plus le nombre d’années est grand, plus c’est ancien : 2,5 millions d’années, c’est bien plus loin que 300 000 ans.","type":"ordre","items":[{"id":"a","texte":"Homo erectus apparaît"},{"id":"b","texte":"Homo habilis taille les premiers outils"},{"id":"c","texte":"L’homme de Néandertal disparaît d’Europe"},{"id":"d","texte":"Homo sapiens apparaît en Afrique"}]},{"enonce":"Combien d’années séparent les premiers outils d’*Homo habilis* de l’apparition d’*Homo sapiens* ?","aide":"2,5 millions = 2 500 000. Fais la soustraction : 2 500 000 − 300 000.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"C’est **Homo habilis**, il y a environ 2,5 millions d’années : il taille les premiers outils en pierre."},{"cle":{"type":"ordre","ids":["b","a","d","c"]},"explication":"**2,5 millions d’années → 1,9 million → 300 000 ans → 40 000 ans.** Un million, c’est mille fois mille : les deux premières dates sont de très loin les plus anciennes."},{"cle":{"type":"nombre","valeur":2200000,"tolerance":0},"affichage":"2 200 000 ans","explication":"2 500 000 − 300 000 = **2 200 000 ans**. Notre espèce est toute jeune à l’échelle de la Préhistoire !"}]$ex$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois couches de terre, trois époques","competence":"observer-schema","situation":"Sur le chantier de fouilles de l’abri du Vallon (un site imaginé pour l’exercice), Inès et son équipe d’archéologues ont dégagé trois couches de terre. Chacune garde les traces d’humains qui ont vécu là.","documents":[{"id":"coupe","type":"schema","titre":"La coupe du chantier de fouilles","source":"Schéma imaginé pour l’exercice.","largeur":320,"hauteur":318,"elements":[{"forme":"rect","x":20,"y":14,"l":280,"h":24,"teinte":"vert","motif":"clair","texte":"Sol actuel"},{"forme":"rect","id":"z1","zone":true,"x":20,"y":38,"l":280,"h":86,"teinte":"sable","motif":"clair"},{"forme":"rect","id":"z2","zone":true,"x":20,"y":124,"l":280,"h":86,"teinte":"ambre","motif":"clair"},{"forme":"rect","id":"z3","zone":true,"x":20,"y":210,"l":280,"h":86,"teinte":"brun","motif":"clair"},{"forme":"texte","x":28,"y":55,"texte":"Couche A","taille":"petit","gras":true,"ancre":"debut"},{"forme":"texte","x":28,"y":141,"texte":"Couche B","taille":"petit","gras":true,"ancre":"debut"},{"forme":"texte","x":28,"y":227,"texte":"Couche C","taille":"petit","gras":true,"ancre":"debut"},{"forme":"emoji","id":"z4","zone":true,"x":70,"y":86,"emoji":"🪔","taille":26},{"forme":"texte","x":70,"y":115,"texte":"lampe à graisse"},{"forme":"emoji","id":"z5","zone":true,"x":166,"y":86,"emoji":"🪡","taille":26},{"forme":"texte","x":166,"y":115,"texte":"aiguille en os"},{"forme":"emoji","id":"z6","zone":true,"x":258,"y":86,"emoji":"🦴","taille":26},{"forme":"texte","x":258,"y":115,"texte":"os de renne"},{"forme":"emoji","id":"z7","zone":true,"x":70,"y":172,"emoji":"🔥","taille":26},{"forme":"texte","x":70,"y":201,"texte":"charbons de bois"},{"forme":"emoji","id":"z8","zone":true,"x":166,"y":172,"emoji":"🦴","taille":26},{"forme":"texte","x":166,"y":201,"texte":"os de cheval"},{"forme":"chemin","id":"z9","zone":true,"d":"M245 186 L252 160 L259 186 Z M261 186 L268 162 L275 186 Z","ferme":true,"teinte":"gris","motif":"plein"},{"forme":"texte","x":258,"y":201,"texte":"pointes en silex"},{"forme":"chemin","id":"z10","zone":true,"d":"M110 236 Q125 255 110 276 Q95 255 110 236 Z","ferme":true,"teinte":"gris","motif":"plein"},{"forme":"texte","x":110,"y":290,"texte":"biface en silex"},{"forme":"emoji","id":"z11","zone":true,"x":222,"y":258,"emoji":"🦴","taille":26},{"forme":"texte","x":222,"y":287,"texte":"os de cerf"},{"forme":"texte","x":160,"y":312,"texte":"Couche A : datée au carbone 14 d’environ 18 000 ans.","taille":"petit","italique":true}]}],"questions":[{"enonce":"Touche la couche de terre **la plus ancienne**.","aide":"Les couches se déposent les unes sur les autres, comme des feuilles qu’on empile : la première posée finit tout en bas.","type":"zone","document":"coupe","multiple":false},{"enonce":"Range les traces trouvées dans le chantier.","aide":"Attention à l’aiguille : elle est en os, mais quelqu’un l’a taillée et percée.","type":"categories","categories":[{"id":"c0","texte":"Un objet fabriqué par les humains"},{"id":"c1","texte":"Le reste d’un animal chassé"}],"items":[{"id":"i0","texte":"L’os de cerf"},{"id":"i1","texte":"Les pointes en silex"},{"id":"i2","texte":"L’os de renne"},{"id":"i3","texte":"La lampe à graisse"},{"id":"i4","texte":"L’os de cheval"},{"id":"i5","texte":"Le biface en silex"},{"id":"i6","texte":"L’aiguille en os"}]},{"enonce":"Touche **les deux** traces qui montrent que ces humains savaient utiliser le **feu**.","aide":"Pense à tout ce qui a brûlé… ou qui servait à faire brûler quelque chose.","type":"zone","document":"coupe","multiple":true},{"enonce":"Que nous apprennent les os de renne, de cheval et de cerf sur ces humains ?","aide":"Ces humains vivent au Paléolithique : ils prélèvent ce que la nature offre, sans rien produire.","type":"choix","options":[{"id":"a","texte":"Ils vivaient dans des villes."},{"id":"b","texte":"Ils élevaient des troupeaux."},{"id":"c","texte":"Ils cultivaient des champs."},{"id":"d","texte":"Ils vivaient de la chasse."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"C’est la **couche C**, tout en bas : elle s’est déposée la première, puis les couches B et A l’ont recouverte. Plus on creuse, plus on remonte le temps."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0","i6":"c0"}},"explication":"Le **biface**, les **pointes**, l’**aiguille** et la **lampe** ont été fabriqués ; les **os** de renne, de cheval et de cerf sont des restes de repas, laissés après la chasse."},{"cle":{"type":"zone","ids":["z7","z4"]},"explication":"Les **charbons de bois** sont les restes d’un foyer, et la **lampe à graisse** servait à brûler de la graisse pour s’éclairer. Le feu protège, chauffe, éclaire et cuit."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ils vivaient de la **chasse** (et de la cueillette) : ce sont des chasseurs-cueilleurs nomades. L’élevage et l’agriculture n’apparaîtront que bien plus tard, au Néolithique."}]$ex$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Chauvet et Lascaux, deux grottes à 18 000 ans d’écart","competence":"raisonner","situation":"Les deux grottes ornées les plus célèbres de France ont été peintes par des *Homo sapiens*. Pourtant, des milliers de générations séparent leurs artistes. Enquête avec la carte et le tableau.","documents":[{"id":"carte","type":"carte","titre":"Deux grottes ornées du sud de la France","fond":"france","fleuves":["rhone","dordogne","garonne","loire","seine"],"lieux":[{"id":"z1","lieu":"lascaux","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"chauvet","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"lyon","nom":"Lyon","taille":1},{"id":"z4","lieu":"toulouse","nom":"Toulouse","taille":1}],"etiquettes":[{"texte":"Rhône","lon":5.25,"lat":44.95,"style":"mer"},{"texte":"Dordogne","lon":0.2,"lat":44.62,"style":"mer"}],"cadrage":[-2.2,42.6,7.6,47.4]},{"id":"grottes","type":"tableau","titre":"Carte d’identité des deux grottes","source":"Âges obtenus en datant au carbone 14 le charbon de bois des dessins et des foyers.","colonnes":["","Lascaux","Chauvet"],"lignes":[["Où ?","Montignac (Dordogne)","Vallon-Pont-d’Arc (Ardèche)"],["Découverte","1940, par quatre adolescents","1994, par trois spéléologues"],["Âge des peintures","≈ 18 000 ans","≈ 36 000 ans"],["Animaux les plus peints","chevaux, aurochs, cerfs","lions, mammouths, rhinocéros"]],"enteteLignes":true}],"questions":[{"enonce":"La grotte Chauvet se trouve en Ardèche, à l’ouest du Rhône. Touche son repère sur la carte.","aide":"Repère le Rhône : il descend de Lyon vers la Méditerranée. La grotte est juste à sa gauche.","type":"zone","document":"carte","multiple":false},{"enonce":"Dans le tableau, touche la case qui prouve que Chauvet est la grotte **la plus ancienne**.","aide":"Cherche la ligne qui donne l’âge des peintures.","type":"zone","document":"grottes","multiple":false},{"enonce":"Combien d’années séparent les peintures de Chauvet de celles de Lascaux ?","aide":"Fais la différence entre les deux âges du tableau.","type":"nombre","unite":"ans"},{"enonce":"À Chauvet, on a peint des lions et des rhinocéros, qu’on ne voit plus en France. Qu’en déduis-tu ?","aide":"Les chasseurs-cueilleurs peignent le gibier et les bêtes qu’ils croisent autour d’eux.","type":"choix","options":[{"id":"a","texte":"Ces animaux vivaient alors en France : les paysages et le climat étaient différents."},{"id":"b","texte":"Les artistes avaient voyagé jusqu’en Afrique pour les voir."},{"id":"c","texte":"Ce sont des animaux imaginaires, inventés par les artistes."},{"id":"d","texte":"Les artistes ont recopié des dessins venus d’une autre grotte."}],"multiple":false},{"enonce":"Complète la conclusion de l’enquête.","aide":"Relis la source sous le tableau pour le deuxième mot.","type":"trous","segments":["Ces peintures sont des ",0," laissées par les humains du Paléolithique. Leur âge a été mesuré grâce au ",1," 14. Représenter le monde sur une paroi prouve une pensée ",2,"."],"banque":["traces","ruines","agricole","fer","symbolique","carbone"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Chauvet est le repère **B**, près du Rhône. Le repère A, près de la Dordogne, est Lascaux."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"La case **« ≈ 36 000 ans »** : les peintures de Chauvet sont deux fois plus vieilles que celles de Lascaux (≈ 18 000 ans)."},{"cle":{"type":"nombre","valeur":18000,"tolerance":0},"affichage":"18 000 ans","explication":"36 000 − 18 000 = **18 000 ans**. Les artistes de Lascaux vivaient aussi loin de ceux de Chauvet que nous vivons loin… de Lascaux !"},{"cle":{"type":"choix","ids":["a"]},"explication":"**Ces animaux vivaient en France à l’époque** : lions des cavernes, rhinocéros laineux et mammouths peuplaient les steppes de l’Europe glaciaire. Les peintures sont aussi des traces de l’environnement."},{"cle":{"type":"trous","trous":[["traces"],["carbone"],["symbolique"]]},"affichage":"traces · carbone · symbolique","explication":"Ce sont des **traces**, datées au **carbone** 14. Peindre des animaux qui ne sont pas là, c’est penser avec des images : une pensée **symbolique**."}]$ex$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le grand voyage d’Homo sapiens","competence":"lire-carte","situation":"Notre espèce est née en Afrique. Comment s’est-elle retrouvée sur tous les continents ? Suis ses routes sur la carte, puis lis les dates dans le tableau.","documents":[{"id":"carte","type":"carte","titre":"Les routes du peuplement de la planète","fond":"monde","cadrage":[-180,-50,180,78],"lieux":[{"id":"z1","lon":36,"lat":0,"symbole":"etoile","teinte":"corail","taille":3},{"id":"z2","lon":44,"lat":34,"symbole":"lettre","lettre":"A","teinte":"encre"},{"id":"z3","lon":134,"lat":-25,"symbole":"lettre","lettre":"B","teinte":"encre"},{"id":"z4","lon":8,"lat":48,"symbole":"lettre","lettre":"C","teinte":"encre"},{"id":"z5","lon":-100,"lat":42,"symbole":"lettre","lettre":"D","teinte":"encre"}],"traits":[{"points":[[36,3],[39,29]],"style":"fleche","teinte":"corail"},{"points":[[48,26],[66,24],[84,19],[101,12],[114,-4],[127,-17]],"style":"fleche","teinte":"corail"},{"points":[[36,38],[24,43],[13,47]],"style":"fleche","teinte":"corail"},{"points":[[75,38],[105,48],[140,60],[179,66]],"style":"ligne","teinte":"corail"},{"points":[[-179,66],[-150,63],[-125,55],[-106,46]],"style":"fleche","teinte":"corail"},{"points":[[-97,33],[-82,10],[-68,-18]],"style":"fleche","teinte":"corail"}],"legende":[{"teinte":"corail","symbole":"etoile","texte":"Le point de départ"},{"teinte":"corail","texte":"Les routes d’Homo sapiens"}],"muette":true,"etiquettes":[{"texte":"Afrique","lon":14,"lat":6,"style":"pays"},{"texte":"Europe","lon":22,"lat":56,"style":"pays"},{"texte":"Asie","lon":100,"lat":32,"style":"pays"},{"texte":"Amérique","lon":-95,"lat":62,"style":"pays"},{"texte":"Océanie","lon":150,"lat":-40,"style":"pays"}]},{"id":"dates","type":"tableau","titre":"Quand les humains arrivent-ils ?","colonnes":["Région atteinte","Il y a environ…"],"lignes":[["L’Europe","45 000 ans"],["Le Proche-Orient","100 000 à 60 000 ans"],["L’Amérique","20 000 à 15 000 ans"],["L’Australie","50 000 ans"]],"enteteLignes":true}],"questions":[{"enonce":"D’après la carte, de quel continent partent toutes les routes ?","aide":"Cherche l’étoile : c’est le point de départ. Lis le nom du continent où elle se trouve.","type":"texte","placeholder":"un continent"},{"enonce":"D’après le tableau, quelle région a été peuplée **en dernier** ? Touche son repère sur la carte.","aide":"Dans le tableau, cherche le plus petit nombre d’années : c’est l’arrivée la plus récente.","type":"zone","document":"carte","multiple":false},{"enonce":"Range les régions dans l’ordre où les humains les ont atteintes.","aide":"Plus le nombre d’années est grand, plus l’arrivée est ancienne.","type":"ordre","items":[{"id":"a","texte":"L’Australie"},{"id":"b","texte":"L’Amérique"},{"id":"c","texte":"Le Proche-Orient"},{"id":"d","texte":"L’Europe"}]},{"enonce":"Regarde la carte : pour atteindre l’Australie depuis l’Asie, il faut franchir des bras de mer. Qu’en déduis-tu ?","aide":"Il n’y a pas de glace sous les tropiques, et un bras de mer ne se traverse pas à la nage avec toute sa famille.","type":"choix","options":[{"id":"a","texte":"Ces humains ont traversé à la nage."},{"id":"b","texte":"L’Australie était collée à l’Afrique."},{"id":"c","texte":"Ces humains ont traversé à pied sur la glace."},{"id":"d","texte":"Ces humains savaient déjà naviguer."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"texte","acceptes":["afrique","l afrique","de l afrique","en afrique"]},"affichage":"Afrique","explication":"Toutes les routes partent d’**Afrique** : c’est là qu’est né *Homo sapiens*, il y a environ 300 000 ans."},{"cle":{"type":"zone","ids":["z5"]},"explication":"C’est l’**Amérique** (repère D), il y a 20 000 à 15 000 ans seulement : c’est le dernier continent atteint."},{"cle":{"type":"ordre","ids":["c","a","d","b"]},"explication":"**Proche-Orient** (100 000 à 60 000 ans) → **Australie** (50 000 ans) → **Europe** (45 000 ans) → **Amérique** (20 000 à 15 000 ans)."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ils savaient **naviguer** : il y a 50 000 ans, des humains ont franchi la mer sur des radeaux ou des embarcations."}]$ex$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Partir un peu plus loin, s’adapter partout","competence":"analyser-texte","situation":"Voici trois scènes de la vie des premiers *Homo sapiens*, racontées pour l’exercice. Elles se passent à des milliers de kilomètres les unes des autres, mais racontent la même histoire.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Trois groupes, trois milieux","source":"Récit imaginé pour l’exercice, d’après ce que les archéologues ont découvert.","blocs":["Dans la steppe glacée d’Europe, le vent souffle sans arrêt. Le groupe d’Aska coud des vêtements de peau avec de fines aiguilles en os. Le soir, sous l’abri, des lampes à graisse éclairent les parois.","Dans une forêt chaude d’Asie du Sud-Est, le groupe de Tani n’a pas besoin de gros abris : quelques branches et de grandes feuilles suffisent à bâtir des huttes légères, qu’on démonte en quelques heures.","Plus loin, au bord de l’océan, les pêcheurs de Mako taillent des hameçons dans des coquillages et tressent des filets. Le poisson est leur principale nourriture.","Un matin, le vieux Bako réunit le groupe d’Aska : « Les rennes ne passent plus par notre vallée. Les pluies ne viennent plus, et la source est à sec depuis deux étés. Et nous sommes devenus trop nombreux : il n’y a plus assez de place pour tous nos abris. Demain, nous irons nous installer au-delà de la colline. »"]}],"questions":[{"enonce":"Touche les **trois objets** qui permettent au groupe d’Aska de vivre dans le froid.","aide":"Cherche ce que le groupe fabrique pour se couvrir… et pour s’éclairer pendant les longues nuits.","type":"zone","document":"recit","multiple":true,"portee":[0]},{"enonce":"Associe chaque milieu à la solution que les humains ont trouvée.","aide":"Relis les trois premiers paragraphes : un milieu par paragraphe.","type":"association","gauche":[{"id":"g0","texte":"Le froid de la steppe"},{"id":"g1","texte":"La chaleur des tropiques"},{"id":"g2","texte":"Le bord de l’océan"}],"droite":[{"id":"d0","texte":"Des huttes légères de branches et de feuilles"},{"id":"d1","texte":"Des vêtements cousus et des lampes à graisse"},{"id":"d2","texte":"Des hameçons et des filets pour pêcher"}]},{"enonce":"Dans le dernier paragraphe, Bako donne trois raisons de partir. Range chacune de ses phrases.","aide":"Les rennes sont des animaux chassés ; la pluie et la sécheresse, c’est le temps qu’il fait.","type":"categories","categories":[{"id":"c0","texte":"Le gibier"},{"id":"c1","texte":"Le climat"},{"id":"c2","texte":"Un groupe trop nombreux"}],"items":[{"id":"i0","texte":"Il n’y a plus assez de place pour tous nos abris."},{"id":"i1","texte":"Nous sommes devenus trop nombreux."},{"id":"i2","texte":"La source est à sec depuis deux étés."},{"id":"i3","texte":"Les pluies ne viennent plus."},{"id":"i4","texte":"Les rennes ne passent plus par notre vallée."}]},{"enonce":"« Demain, nous irons nous installer au-delà de la colline. » Que montre cette phrase sur la façon dont les humains ont peuplé la planète ?","aide":"Le groupe ne part pas à l’autre bout du monde : il va juste de l’autre côté de la colline.","type":"choix","options":[{"id":"a","texte":"Ils savaient dès le départ qu’ils iraient jusqu’en Australie."},{"id":"b","texte":"Ils fuyaient une guerre contre un autre groupe."},{"id":"c","texte":"Ils ont traversé les continents en un seul grand voyage."},{"id":"d","texte":"Ils ont avancé peu à peu, un peu plus loin à chaque génération."}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17","m23","m32"]},"explication":"Les **vêtements** de peau, les **aiguilles** en os qui servent à les coudre et les **lampes** à graisse : des techniques inventées pour vivre dans le froid."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**Froid → vêtements cousus et lampes**, **tropiques → huttes légères**, **côtes → pêche**. L’humain n’est pas fait pour un seul milieu : il fabrique de quoi vivre dans tous."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c2","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Le **gibier** s’en va, le **climat** change (plus de pluie, source à sec) et le **groupe grandit** : ce sont les trois grandes causes des migrations."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ils ont avancé **peu à peu** : chaque génération s’installait un peu plus loin. Ces déplacements se comptent en millénaires ; personne n’est « parti pour l’Australie »."}]$ex$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Béring : passer en Amérique à pied sec","competence":"raisonner","situation":"Aujourd’hui, l’Asie et l’Amérique sont séparées par la mer, au détroit de Béring. Pourtant, les premiers Américains sont venus d’Asie… à pied. Croise le texte et la coupe pour comprendre comment.","documents":[{"id":"texte","type":"texte","genre":"article","titre":"Ce que disent les scientifiques","source":"Texte écrit pour l’exercice, d’après les connaissances actuelles.","blocs":["Il y a environ 20 000 ans, la Terre traverse une glaciation. D’immenses glaciers couvrent le nord de l’Amérique et de l’Europe. L’eau qui forme ces glaces vient des océans : le niveau des mers baisse de 120 mètres.","Entre la Sibérie et l’Alaska, là où s’étend aujourd’hui le détroit de Béring, large d’environ 80 km, apparaît alors une immense plaine couverte d’herbe : la Béringie. Des mammouths, des bisons et des chevaux y broutent.","Des groupes de chasseurs venus de Sibérie suivent ce gibier et gagnent l’Amérique, sans savoir qu’ils changent de continent. L’étude de l’ADN le confirme : les premiers Américains ont pour ancêtres des populations d’Asie."]},{"id":"coupe","type":"schema","titre":"Le détroit de Béring vu en coupe","source":"Schéma simplifié ; hauteurs exagérées.","largeur":320,"hauteur":272,"elements":[{"forme":"texte","x":20,"y":22,"texte":"Aujourd’hui","gras":true,"ancre":"debut"},{"forme":"polygone","points":[[20,44],[104,46],[124,70],[124,112],[20,112]],"teinte":"brun","motif":"clair"},{"forme":"polygone","points":[[196,70],[216,46],[300,44],[300,112],[196,112]],"teinte":"brun","motif":"clair"},{"forme":"rect","x":124,"y":70,"l":72,"h":20,"teinte":"bleu","motif":"clair"},{"forme":"rect","x":124,"y":90,"l":72,"h":22,"teinte":"brun","motif":"clair"},{"forme":"texte","x":62,"y":86,"texte":"ASIE","gras":true},{"forme":"texte","x":258,"y":86,"texte":"AMÉRIQUE","gras":true},{"forme":"ligne","de":[20,70],"a":[300,70],"style":"pointilles","teinte":"bleu","epaisseur":1},{"forme":"texte","x":160,"y":64,"texte":"niveau de la mer","taille":"petit","teinte":"bleu"},{"forme":"ligne","de":[160,72],"a":[160,89],"fleche":"deux","teinte":"encre","epaisseur":1},{"forme":"texte","x":160,"y":106,"texte":"50 m","taille":"petit","gras":true},{"forme":"texte","x":20,"y":146,"texte":"Il y a 20 000 ans","gras":true,"ancre":"debut"},{"forme":"polygone","points":[[20,168],[104,170],[124,194],[124,214],[196,214],[196,194],[216,170],[300,168],[300,262],[20,262]],"teinte":"brun","motif":"clair"},{"forme":"texte","x":62,"y":210,"texte":"ASIE","gras":true},{"forme":"texte","x":258,"y":210,"texte":"AMÉRIQUE","gras":true},{"forme":"emoji","x":146,"y":202,"emoji":"🦣","taille":20},{"forme":"emoji","x":176,"y":202,"emoji":"🚶","taille":20},{"forme":"emoji","x":44,"y":158,"emoji":"❄️","taille":16},{"forme":"emoji","x":280,"y":158,"emoji":"❄️","taille":16},{"forme":"ligne","de":[20,194],"a":[300,194],"style":"pointilles","teinte":"gris","epaisseur":1},{"forme":"texte","x":160,"y":188,"texte":"niveau actuel","taille":"petit","teinte":"gris"},{"forme":"ligne","de":[20,242],"a":[300,242],"style":"pointilles","teinte":"bleu","epaisseur":2},{"forme":"texte","x":160,"y":256,"texte":"niveau de la mer il y a 20 000 ans : 120 m plus bas","taille":"petit","teinte":"bleu","gras":true}]}],"questions":[{"enonce":"D’après la coupe, au plus profond, le fond du détroit est à 50 m sous la mer. Il y a 20 000 ans, la mer était 120 m plus bas. À combien de mètres **au-dessus** de la mer se trouvait alors ce fond ?","aide":"D’après la coupe, le fond est à 50 m sous le niveau actuel, et la mer d’alors 120 m sous ce niveau : calcule l’écart entre les deux.","type":"nombre","unite":"m"},{"enonce":"D’après le texte, pourquoi le niveau des mers était-il si bas il y a 20 000 ans ?","aide":"Relis le premier paragraphe : d’où vient l’eau qui forme les glaces ?","type":"choix","options":[{"id":"a","texte":"Une grande partie de l’eau était piégée dans les glaciers."},{"id":"b","texte":"Le fond des océans s’était soulevé."},{"id":"c","texte":"Il pleuvait beaucoup moins qu’aujourd’hui."},{"id":"d","texte":"Les humains avaient creusé de grands canaux."}],"multiple":false},{"enonce":"Touche le nom de la région d’où venaient les chasseurs qui ont gagné l’Amérique.","aide":"Relis le début du dernier paragraphe : « des groupes de chasseurs venus de… »","type":"zone","document":"texte","multiple":false,"portee":[2]},{"enonce":"Pourquoi ces chasseurs sont-ils passés d’Asie en Amérique ?","aide":"Relis le texte : que font les mammouths, les bisons et les chevaux, et que font les chasseurs ?","type":"choix","options":[{"id":"a","texte":"Ils suivaient les troupeaux qu’ils chassaient."},{"id":"b","texte":"Ils cherchaient des terres à cultiver."},{"id":"c","texte":"Ils voulaient découvrir un nouveau continent."},{"id":"d","texte":"Ils fuyaient la montée des eaux."}],"multiple":false},{"enonce":"Complète la conclusion de l’enquête.","aide":"Relis le dernier paragraphe du texte, puis la coupe : que devient la mer quand les glaces fondent ?","type":"trous","segments":["Les premiers habitants de l’Amérique sont venus d’",0,". Ils sont passés ",1,", il y a environ 20 000 à 15 000 ans. Aujourd’hui, on ne peut plus passer : les glaces ont fondu et la mer est ",2,"."],"banque":["Asie","en bateau","à pied","descendue","remontée","Europe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":70,"tolerance":0},"affichage":"70 m","explication":"120 − 50 = **70 m** : même au plus profond, le fond du détroit était 70 m au-dessus de la mer. On pouvait passer à pied !"},{"cle":{"type":"choix","ids":["a"]},"explication":"Pendant la glaciation, une énorme quantité d’eau était **piégée dans les glaciers** : le niveau des mers avait baissé de 120 m."},{"cle":{"type":"zone","ids":["m87"]},"explication":"Ils venaient de **Sibérie**, au nord-est de l’Asie. L’ADN des premiers Américains le confirme."},{"cle":{"type":"choix","ids":["a"]},"explication":"Ils **suivaient le gibier** : ils ne savaient même pas qu’ils changeaient de continent. Et ils ne cultivaient rien : l’agriculture n’existait pas encore."},{"cle":{"type":"trous","trous":[["asie"],["a pied"],["remontee"]]},"affichage":"Asie · à pied · remontée","explication":"Ils sont venus d’**Asie**, **à pied**, par la Béringie. Quand les glaces ont fondu, la mer est **remontée** et a recouvert le pont de terre : c’est le détroit de Béring d’aujourd’hui."}]$ex$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui décide à Athènes ?","competence":"observer-schema","situation":"Au Ve siècle av. J.-C., Athènes n’a pas de roi. Ce sont les **citoyens** eux-mêmes qui gouvernent la cité. Observe le schéma de leurs institutions.","documents":[{"id":"institutions","type":"schema","titre":"Les institutions de la démocratie athénienne (Ve siècle av. J.-C.)","largeur":340,"hauteur":262,"elements":[{"forme":"rect","x":14,"y":14,"l":152,"h":32,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Ecclésia","id":"z1","zone":true},{"forme":"texte","x":90,"y":64,"texte":"l’assemblée des citoyens"},{"forme":"texte","x":90,"y":78,"texte":"vote les lois, la guerre"},{"forme":"texte","x":90,"y":92,"texte":"et la paix"},{"forme":"rect","x":174,"y":14,"l":152,"h":32,"arrondi":8,"teinte":"turquoise","motif":"clair","texte":"Boulè","id":"z2","zone":true},{"forme":"texte","x":250,"y":64,"texte":"500 membres"},{"forme":"texte","x":250,"y":78,"texte":"tirés au sort"},{"forme":"texte","x":250,"y":92,"texte":"préparent les lois"},{"forme":"rect","x":14,"y":110,"l":152,"h":32,"arrondi":8,"teinte":"turquoise","motif":"clair","texte":"Héliée","id":"z3","zone":true},{"forme":"texte","x":90,"y":160,"texte":"6 000 jurés"},{"forme":"texte","x":90,"y":174,"texte":"tirés au sort"},{"forme":"texte","x":90,"y":188,"texte":"rendent la justice"},{"forme":"rect","x":174,"y":110,"l":152,"h":32,"arrondi":8,"teinte":"corail","motif":"clair","texte":"Stratèges","id":"z4","zone":true},{"forme":"texte","x":250,"y":160,"texte":"10 magistrats"},{"forme":"texte","x":250,"y":174,"texte":"élus"},{"forme":"texte","x":250,"y":188,"texte":"commandent l’armée"},{"forme":"rect","x":14,"y":212,"l":312,"h":34,"arrondi":17,"teinte":"sable","motif":"clair","texte":"Les citoyens : environ 40 000 hommes"}],"legende":[{"teinte":"violet","motif":"clair","texte":"Ouverte à tous les citoyens"},{"teinte":"turquoise","motif":"clair","texte":"Membres tirés au sort"},{"teinte":"corail","motif":"clair","texte":"Membres élus"}]}],"questions":[{"enonce":"Touche l’institution qui **vote les lois**.","aide":"Lis les lignes écrites sous chaque case.","type":"zone","document":"institutions","multiple":false},{"enonce":"Combien de citoyens siègent à la **Boulè** ?","aide":"Cherche la case de la Boulè, puis lis le nombre écrit dessous.","type":"nombre","unite":"citoyens"},{"enonce":"Élus ou tirés au sort ? Range chaque groupe.","aide":"Aide-toi de la légende : chaque couleur dit comment on désigne les membres.","type":"categories","categories":[{"id":"c0","texte":"Tirés au sort"},{"id":"c1","texte":"Élus"}],"items":[{"id":"i0","texte":"Les jurés de l’Héliée"},{"id":"i1","texte":"Les membres de la Boulè"},{"id":"i2","texte":"Les stratèges"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"C’est l’**Ecclésia**, l’assemblée de tous les citoyens. Elle se réunit environ 40 fois par an sur la colline de la Pnyx."},{"cle":{"type":"nombre","valeur":500,"tolerance":0},"affichage":"500 citoyens","explication":"La Boulè compte **500** citoyens tirés au sort. Elle prépare les lois que l’Ecclésia votera."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1"}},"explication":"Boulè et Héliée sont **tirées au sort** : pour les Athéniens, c’est le moyen le plus égalitaire. Seuls les **stratèges**, qui commandent l’armée, sont **élus** : il faut des chefs compétents."}]$ex$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le tesson d’Aristide","competence":"analyser-document","situation":"Une fois par an, les Athéniens peuvent chasser de la cité un citoyen jugé dangereux, en écrivant son nom sur un morceau de poterie : c’est l’**ostracisme**. Plutarque raconte comment on votait.","documents":[{"id":"plutarque","type":"texte","genre":"source","titre":"Comment se déroule un ostracisme","auteur":"D’après Plutarque, Vie d’Aristide, 7 (vers 100 apr. J.-C.)","blocs":["Chaque citoyen prend un tesson de poterie, un *ostrakon*, et y écrit le nom de celui qu’il veut voir quitter la cité. Il le porte sur l’agora, dans un enclos fermé par des barrières.","Les magistrats comptent d’abord tous les tessons : s’il y en a moins de six mille, le vote ne compte pas. Sinon, celui dont le nom revient le plus souvent est banni de la cité pour dix ans. Il garde cependant ses biens.","On raconte que, le jour où l’on vota contre Aristide, surnommé « le Juste », un paysan qui ne savait pas écrire tendit son tesson à Aristide lui-même, sans le reconnaître, et lui demanda d’y écrire « Aristide ». Surpris, celui-ci lui demanda quel tort Aristide lui avait fait. « Aucun, répondit l’homme, je ne le connais même pas ; mais je suis agacé de l’entendre partout appeler le Juste. » Aristide écrivit son nom sans rien dire et rendit le tesson."]},{"id":"depouillement","type":"tableau","titre":"Le dépouillement d’un ostracisme","source":"Noms et chiffres imaginés pour l’exercice.","colonnes":["Nom écrit sur le tesson","Nombre de tessons"],"lignes":[["Criton","1 150"],["Philon","2 870"],["Lycon","2 380"],["Timon","300"]],"enteteLignes":true}],"questions":[{"enonce":"D’après le Doc 1, pendant combien d’années un citoyen ostracisé doit-il quitter Athènes ?","aide":"Relis le paragraphe 2 : il donne la durée du bannissement.","type":"nombre","unite":"ans"},{"enonce":"Combien de tessons les magistrats ont-ils comptés **en tout** lors du vote du Doc 2 ?","aide":"Additionne les quatre nombres de la colonne de droite.","type":"nombre","unite":"tessons"},{"enonce":"Le vote est donc valable. Touche, dans le Doc 2, le **nom** du citoyen qui doit partir en exil.","aide":"Cherche le nom écrit sur le plus grand nombre de tessons.","type":"zone","document":"depouillement","multiple":false},{"enonce":"Dans le paragraphe 3, touche le mot qui dit ce que le paysan ressent envers Aristide.","aide":"Le paysan explique pourquoi il vote contre Aristide. Cherche dans sa réponse, entre guillemets.","type":"zone","document":"plutarque","multiple":false},{"enonce":"Que montre l’histoire d’Aristide et du paysan ?","aide":"Aristide avait-il fait du tort au paysan ? Relis la réponse de l’homme.","type":"choix","options":[{"id":"a","texte":"Aristide a triché pour ne pas être banni"},{"id":"b","texte":"Le paysan voulait punir Aristide pour un vol"},{"id":"c","texte":"Seuls les citoyens qui savaient écrire pouvaient voter"},{"id":"d","texte":"On pouvait être banni sans avoir commis aucun crime"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 ans","explication":"Le banni doit quitter la cité pendant **10 ans**. Il garde ses biens : ce n’est pas la punition d’un crime, mais une mise à l’écart."},{"cle":{"type":"nombre","valeur":6700,"tolerance":0},"affichage":"6700 tessons","explication":"1 150 + 2 870 + 2 380 + 300 = **6 700 tessons**. C’est plus de six mille : d’après Plutarque, le vote compte."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"C’est **Philon** : son nom revient 2 870 fois, plus que tous les autres. Il est banni pour dix ans."},{"cle":{"type":"zone","ids":["m140"]},"explication":"Le paysan est **agacé** d’entendre Aristide appelé « le Juste ». Il vote contre lui par simple agacement, sans même le connaître."},{"cle":{"type":"choix","ids":["d"]},"explication":"**On pouvait être banni sans avoir commis de crime** : l’ostracisme écartait un homme jugé trop puissant… ou simplement trop admiré. Athènes invente la démocratie et, en même temps, le moyen de s’en protéger."}]$ex$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le pouvoir au plus grand nombre ?","competence":"argumenter","situation":"En 431 av. J.-C., Périclès fait devant les Athéniens l’éloge de leur démocratie. Confronte son discours à ce que les historiens savent des habitants d’Athènes.","documents":[{"id":"pericles","type":"texte","genre":"source","titre":"Périclès parle de la démocratie","auteur":"D’après Thucydide, La Guerre du Péloponnèse, II, 37 (discours de Périclès, 431 av. J.-C.)","blocs":["Notre constitution n’imite pas les lois de nos voisins : c’est plutôt nous qui servons de modèle aux autres. Parce que le pouvoir y est entre les mains non d’une minorité, mais du plus grand nombre, on lui a donné le nom de démocratie.","Pour les affaires privées, tous sont égaux devant la loi. Pour les charges publiques, on ne regarde pas la famille ou la fortune, mais le mérite ; et la pauvreté n’empêche personne de servir la cité, s’il en est capable."]},{"id":"population","type":"graphique","forme":"secteurs","titre":"Les habitants de l’Athènes de Périclès (environ 300 000 personnes)","source":"Estimations arrondies : les historiens discutent encore ces chiffres.","categories":["Citoyens","Femmes et enfants des familles de citoyens","Métèques et leurs familles","Esclaves"],"series":[{"nom":"Part des habitants","valeurs":[13,30,10,47]}]}],"questions":[{"enonce":"Selon Périclès, entre les mains de qui est le pouvoir à Athènes ? Touche les **trois mots** qui le disent.","aide":"Périclès oppose deux groupes : « une minorité »… et qui d’autre ?","type":"zone","document":"pericles","multiple":true},{"enonce":"Dans le Doc 2, touche la part des habitants qui ont le droit de voter à l’Ecclésia.","aide":"À l’Ecclésia, seuls votent les hommes de plus de 18 ans nés de parents athéniens.","type":"zone","document":"population","multiple":false},{"enonce":"Quel pourcentage des habitants d’Athènes n’a **pas** le droit de voter ?","aide":"Tous les habitants réunis font 100 %. Enlève la part des citoyens.","type":"nombre","unite":"%"},{"enonce":"Périclès parle du « plus grand nombre ». Comment expliquer l’écart entre son discours et le Doc 2 ?","aide":"Le « plus grand nombre »… de qui ? De tous les habitants, ou seulement des citoyens ?","type":"choix","options":[{"id":"a","texte":"Périclès ne savait pas combien Athènes comptait d’habitants"},{"id":"b","texte":"À l’époque de Périclès, tous les habitants votaient à l’Ecclésia"},{"id":"c","texte":"Les esclaves votaient à la place de leurs maîtres"},{"id":"d","texte":"Pour Périclès, le peuple, ce sont les citoyens : femmes, métèques et esclaves n’en font pas partie"}],"multiple":false},{"enonce":"Complète la conclusion de l’enquête.","aide":"Le premier mot dit COMMENT on vote ; le second dit QUI peut voter.","type":"trous","segments":["La démocratie athénienne est ",0," : les citoyens votent eux-mêmes les lois, sans élire de représentants. Mais elle est ",1," : environ 87 % des habitants n’ont pas le droit de voter."],"banque":["restreinte","représentative","universelle","directe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m35","m36","m37"]},"explication":"Pour Périclès, le pouvoir appartient au **plus grand nombre** : c’est le sens même du mot démocratie, le pouvoir (*kratos*) du peuple (*dêmos*)."},{"cle":{"type":"zone","ids":["k0"]},"explication":"Seuls les **citoyens** votent : environ 13 % des habitants."},{"cle":{"type":"nombre","valeur":87,"tolerance":0},"affichage":"87 %","explication":"100 − 13 = **87 %** : près de neuf habitants sur dix n’ont pas le droit de vote — femmes, enfants, métèques et esclaves."},{"cle":{"type":"choix","ids":["d"]},"explication":"Périclès ne parle que **des citoyens** : parmi eux, c’est bien la majorité qui décide. Mais les citoyens ne sont qu’une petite partie des habitants."},{"cle":{"type":"trous","trous":[["directe"],["restreinte","reservee"]]},"affichage":"directe · restreinte","explication":"Une démocratie **directe** (chaque citoyen vote lui-même les lois) mais **restreinte** : elle exclut les femmes, les métèques et les esclaves. La nôtre est représentative et universelle."}]$ex$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"De la petite cité au grand empire","competence":"se-reperer-temps","situation":"Au départ, Rome n’est qu’une petite cité du Latium, en Italie. En quelques siècles, elle conquiert tout le tour de la Méditerranée. Observe la frise de ses grandes étapes.","documents":[{"id":"frise","type":"frise","titre":"Les grandes étapes de la puissance romaine","debut":-300,"fin":200,"pas":50,"periodes":[{"id":"z1","debut":-264,"fin":-146,"nom":"Guerres puniques","teinte":"ambre"},{"id":"z2","debut":-27,"fin":180,"nom":"Paix romaine","teinte":"turquoise"}],"evenements":[{"id":"z3","date":-146,"nom":"Carthage détruite"},{"id":"z4","date":-52,"nom":"Alésia"},{"id":"z5","date":-27,"nom":"Auguste empereur"},{"id":"z6","date":117,"nom":"Apogée sous Trajan"}]}],"questions":[{"enonce":"Touche l’événement qui marque le **début de l’Empire**, quand Rome est gouvernée par un empereur.","aide":"Cherche le nom du premier empereur romain sur la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années ont duré les **guerres puniques** contre Carthage ?","aide":"Les deux dates sont avant J.-C. : de 264 à 146 av. J.-C., on soustrait la plus petite de la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Range chaque événement : a-t-il eu lieu **avant** ou **après** la naissance de Jésus-Christ ?","aide":"Sur la frise, tout ce qui est à gauche du repère « J.-C. » est avant J.-C. ; tout ce qui est à droite est après.","type":"categories","categories":[{"id":"c0","texte":"Avant J.-C."},{"id":"c1","texte":"Après J.-C."}],"items":[{"id":"i0","texte":"La fin de la paix romaine"},{"id":"i1","texte":"L’Empire atteint sa plus grande étendue"},{"id":"i2","texte":"La reddition de Vercingétorix à Alésia"},{"id":"i3","texte":"La destruction de Carthage"},{"id":"i4","texte":"Octave devient Auguste, premier empereur"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"En **27 av. J.-C.**, Octave reçoit le titre d’**Auguste** : il devient le premier empereur, et la paix romaine commence."},{"cle":{"type":"nombre","valeur":118,"tolerance":0},"affichage":"118 ans","explication":"264 − 146 = **118 ans** : plus d’un siècle de guerre, jusqu’à la destruction de Carthage."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"Carthage (146), Alésia (52) et Auguste (27) sont **av. J.-C.** ; l’apogée sous Trajan (117) et la fin de la paix romaine (180) sont **apr. J.-C.**"}]$ex$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une paix gagnée par les armes","competence":"lire-carte","situation":"Juste avant de mourir, en 14 apr. J.-C., l’empereur Auguste fait graver le récit de ses « hauts faits ». Cent ans plus tard, sous Trajan, l’Empire est plus grand que jamais. Compare la carte et le texte.","documents":[{"id":"carte","type":"carte","titre":"L’Empire romain, d’Auguste à Trajan","fond":"mediterranee","fleuves":["rhin","danube","nil","euphrate","tigre","tibre"],"aires":[{"id":"z3","contour":[[-9.8,33.6],[-5,34],[-2,34.6],[2,35.3],[5,35],[6.5,34.8],[8,34.4],[9.5,33.4],[11,32.3],[14,31.1],[18,30.4],[20,30.4],[23,31.3],[25,30.7],[28.5,29.3],[30,26],[32,23.4],[35.8,23.4],[37.5,24.5],[37.8,26.5],[38.8,27.2],[39.5,29.5],[38.6,31.5],[39,33],[40.6,34.4],[42.5,33.6],[44.5,32],[47.5,30],[48.8,30.3],[47.5,32.5],[46.2,34.2],[45.5,36],[44.5,37.3],[45.2,38.8],[47.5,39.8],[46.5,41.3],[43.5,42.2],[41.7,41.7],[39.7,41.2],[38,42.5],[33,44],[30.5,45],[29.7,45.3],[28.2,46.5],[26.5,47.6],[24.5,48],[23,47.7],[22,46.9],[21.2,45.9],[20.4,45.2],[19.3,45.2],[18.9,46],[19,47.8],[17.9,47.75],[16.4,48.2],[13.4,48.6],[12.1,49],[11.8,48.95],[10.5,49],[9.7,48.85],[9.4,49.5],[9.2,50],[8.9,50.4],[8.3,50.4],[7.7,50.5],[7,50.9],[6.2,51.8],[4.5,52.1],[3,53],[1,55],[-4,55],[-6,54],[-6,50],[-5.5,48.2],[-10,44],[-10,36]],"teinte":"ambre","motif":"hachures","surTerre":true},{"id":"z4","contour":[[-10,43.8],[-4,44.5],[-5,48.8],[2,51.3],[4.2,52.2],[6.1,51.8],[7,50.9],[7.6,50.35],[8.3,50],[8.4,49],[7.6,47.6],[9.2,47.6],[10,48.4],[11.4,48.75],[12.1,49],[13.4,48.6],[16.4,48.2],[17.9,47.75],[19,47.8],[18.9,46],[19.3,45.2],[20.5,44.85],[22.5,44.6],[24.9,43.7],[26,43.9],[28,44.1],[29.7,45.2],[30.5,44.5],[28.6,43.4],[26,42.9],[23.5,42.8],[23,41.5],[24.7,40.8],[25.5,39.5],[26.5,40.2],[29.1,41.3],[31.5,41.6],[35,42.3],[36.5,41.4],[37.5,40.3],[36,39],[34,38.5],[33.8,37.4],[35.2,37.3],[36.3,37.2],[37.8,36.8],[38.3,36],[38.5,34.5],[37,33],[36,31.5],[35.5,31],[35,30.5],[34.3,31.2],[32.5,30],[33.5,27],[33,24],[30.5,24],[28.5,29],[25.2,31.5],[20,30.5],[18.5,30.2],[15,31],[12,32],[10,33.2],[8.5,34.5],[6.2,36.5],[6.3,37.4],[-5.4,36.2],[-9.5,36.8]],"teinte":"rose","motif":"plein","surTerre":true}],"traits":[{"id":"z2","points":[[6.2,51.8],[7,50.9],[7.7,50.5],[8.3,50.4],[8.9,50.4],[9.2,50],[9.4,49.5],[9.7,48.85],[10.5,49],[11.8,48.95],[13.4,48.6],[16.4,48.2],[17.9,47.75],[19,47.8],[18.9,46],[19.3,45.2]],"style":"pointilles","teinte":"corail","epaisseur":3}],"lieux":[{"id":"z1","lieu":"rome","nom":"Rome","symbole":"etoile","teinte":"encre"}],"legende":[{"teinte":"rose","motif":"plein","texte":"L’Empire à la mort d’Auguste (14 apr. J.-C.)"},{"teinte":"ambre","motif":"hachures","texte":"Les conquêtes de 14 à 117 (mort de Trajan)"},{"teinte":"corail","texte":"Le limes du Rhin et du Danube"},{"teinte":"encre","symbole":"etoile","texte":"Rome, la capitale"}]},{"id":"hautsfaits","type":"texte","genre":"source","titre":"Auguste raconte ses « hauts faits »","auteur":"D’après Auguste, Res Gestae (« Hauts faits »), 3, 26 et 13 (vers 14 apr. J.-C.)","blocs":["J’ai souvent fait la guerre, sur terre et sur mer, contre des ennemis de l’intérieur et de l’extérieur, dans le monde entier.","J’ai agrandi le territoire de toutes les provinces du peuple romain qui avaient pour voisins des peuples qui n’obéissaient pas à notre pouvoir.","Nos ancêtres voulaient que le temple de Janus soit fermé quand la paix avait été obtenue par des victoires, sur terre et sur mer, dans tout l’empire du peuple romain. Avant ma naissance, il n’avait été fermé que deux fois depuis la fondation de Rome ; sous mon principat, le Sénat a décidé trois fois de le fermer."]}],"questions":[{"enonce":"Touche les territoires conquis **après** la mort d’Auguste, jusqu’en 117.","aide":"Regarde la légende : les conquêtes d’après Auguste ne sont pas de la même couleur que l’Empire de 14.","type":"zone","document":"carte","multiple":false},{"enonce":"D’après la légende, combien d’années séparent la mort d’Auguste de celle de Trajan ?","aide":"Les deux dates de la légende sont après J.-C. : fais la soustraction.","type":"nombre","unite":"ans"},{"enonce":"Touche le *limes*, la frontière fortifiée où veillent les légions.","aide":"Dans la légende, le limes est en rouge corail. Sur la carte, c’est un trait en pointillés au nord de l’Empire.","type":"zone","document":"carte","multiple":false},{"enonce":"Dans le Doc 2, touche le mot qui dit **comment** la paix a été obtenue.","aide":"Relis le dernier paragraphe : « la paix avait été obtenue par des… ».","type":"zone","document":"hautsfaits","multiple":false},{"enonce":"Que montrent ensemble la carte et le texte ?","aide":"Pense aux guerres dont parle Auguste, aux conquêtes de la carte et au limes.","type":"choix","options":[{"id":"a","texte":"Les frontières de l’Empire ne sont pas surveillées"},{"id":"b","texte":"La paix romaine est imposée et gardée par la force des armées"},{"id":"c","texte":"L’Empire rétrécit sans cesse entre Auguste et Trajan"},{"id":"d","texte":"Rome a obtenu la paix sans jamais combattre"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Ce sont les zones **hachurées en orange** : la Bretagne, la Maurétanie, la Dacie, l’Arabie, l’Arménie et la Mésopotamie. Sous Trajan, en 117, l’Empire atteint sa plus grande taille."},{"cle":{"type":"nombre","valeur":103,"tolerance":0},"affichage":"103 ans","explication":"117 − 14 = **103 ans** : en un siècle, les successeurs d’Auguste ont encore agrandi l’Empire."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **limes** suit le Rhin et le Danube : un chapelet de camps, de fossés et de tours de guet face aux peuples germains."},{"cle":{"type":"zone","ids":["m68"]},"explication":"Par des **victoires** : pour Auguste, la paix se gagne à la guerre. On ferme le temple de Janus une fois les ennemis vaincus."},{"cle":{"type":"choix","ids":["b"]},"explication":"Guerres, conquêtes, frontière fortifiée : la **paix romaine est imposée et maintenue par la force**. À l’intérieur, elle favorise le commerce et les villes."}]$ex$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Tous les pouvoirs sur une pièce d’argent","competence":"analyser-document","situation":"Un marchand de Lugdunum reçoit en paiement une pièce d’argent, un **denier**. Comme toutes les monnaies de l’Empire, elle porte un message : qui gouverne, et avec quels pouvoirs. Décode-la à l’aide du lexique.","documents":[{"id":"piece","type":"schema","titre":"Un denier de l’empereur Trajan","source":"Denier frappé à Rome entre 103 et 111 apr. J.-C. : légendes réelles, dessin simplifié.","largeur":320,"hauteur":200,"elements":[{"forme":"texte","x":84,"y":18,"texte":"AVERS (face)","taille":"petit","gras":true},{"forme":"texte","x":236,"y":18,"texte":"REVERS (pile)","taille":"petit","gras":true},{"forme":"cercle","cx":84,"cy":96,"r":66,"teinte":"gris","motif":"clair"},{"forme":"cercle","cx":236,"cy":96,"r":66,"teinte":"gris","motif":"clair"},{"forme":"emoji","x":84,"y":98,"emoji":"👤","taille":40},{"forme":"emoji","x":236,"y":98,"emoji":"⛓️","taille":32},{"id":"z1","zone":true,"forme":"texte","x":42,"y":76,"texte":"IMP","gras":true},{"id":"z2","zone":true,"forme":"texte","x":84,"y":50,"texte":"TRAIANO","gras":true},{"id":"z3","zone":true,"forme":"texte","x":126,"y":76,"texte":"AVG","gras":true},{"id":"z4","zone":true,"forme":"texte","x":128,"y":112,"texte":"GER","gras":true},{"id":"z5","zone":true,"forme":"texte","x":112,"y":141,"texte":"DAC","gras":true},{"id":"z6","zone":true,"forme":"texte","x":78,"y":152,"texte":"P M","gras":true},{"id":"z7","zone":true,"forme":"texte","x":44,"y":131,"texte":"TR P","gras":true},{"id":"z8","zone":true,"forme":"texte","x":196,"y":70,"texte":"COS V","gras":true},{"id":"z9","zone":true,"forme":"texte","x":236,"y":50,"texte":"P P","gras":true},{"id":"z10","zone":true,"forme":"texte","x":270,"y":72,"texte":"S P Q R","gras":true},{"id":"z11","zone":true,"forme":"texte","x":266,"y":134,"texte":"OPTIMO","gras":true},{"id":"z12","zone":true,"forme":"texte","x":205,"y":136,"texte":"PRINC","gras":true},{"forme":"texte","x":84,"y":184,"texte":"buste de Trajan","taille":"petit","italique":true},{"forme":"texte","x":236,"y":184,"texte":"un Dace captif","taille":"petit","italique":true}]},{"id":"lexique","type":"tableau","titre":"Petit lexique des abréviations","colonnes":["Abréviation","En latin","Ce que cela veut dire"],"lignes":[["IMP","Imperator","Général vainqueur, chef des armées"],["TRAIANO","Traiano","« À Trajan »"],["AVG","Augustus","Auguste : le titre de tous les empereurs depuis Octave"],["GER","Germanicus","Vainqueur des Germains"],["DAC","Dacicus","Vainqueur des Daces, un peuple du Danube"],["P M","Pontifex maximus","Grand pontife : le chef de la religion romaine"],["TR P","Tribunicia potestas","Les pouvoirs d’un tribun du peuple"],["COS","Consul","Consul, la plus haute magistrature de la République"],["P P","Pater patriae","« Père de la patrie »"],["S P Q R","Senatus populusque Romanus","« Le Sénat et le peuple romain »"],["OPTIMO PRINC","Optimo principi","« Au meilleur des princes »"]],"enteteLignes":true}],"questions":[{"enonce":"Sur la pièce, touche le titre que portent **tous les empereurs** depuis Octave.","aide":"Cherche dans le lexique le titre donné à Octave en 27 av. J.-C., puis retrouve son abréviation sur l’avers.","type":"zone","document":"piece","multiple":false},{"enonce":"D’après le revers, combien de fois Trajan a-t-il déjà été **consul** quand cette pièce est frappée ?","aide":"COS veut dire consul. Le signe qui le suit est un chiffre romain.","type":"nombre","unite":"fois"},{"enonce":"Trajan rappelle sa victoire sur un peuple du Danube, en 106. Touche l’abréviation qui le dit.","aide":"Cherche dans le lexique le mot « Danube ».","type":"zone","document":"piece","multiple":false},{"enonce":"Range chaque titre selon le pouvoir qu’il donne à l’empereur.","aide":"Aide-toi de la dernière colonne du lexique : un général, un grand pontife, des magistrats.","type":"categories","categories":[{"id":"c0","texte":"L’armée"},{"id":"c1","texte":"La religion"},{"id":"c2","texte":"Le gouvernement de l’État"}],"items":[{"id":"i0","texte":"P M (pontifex maximus)"},{"id":"i1","texte":"IMP (imperator)"},{"id":"i2","texte":"DAC (vainqueur des Daces)"},{"id":"i3","texte":"COS (consul)"},{"id":"i4","texte":"TR P (pouvoirs de tribun)"}]},{"enonce":"Consul et tribun sont d’anciennes fonctions de la République. Que montre leur présence sur une pièce de Trajan ?","aide":"Regarde QUI porte tous ces titres à la fois.","type":"choix","options":[{"id":"a","texte":"Les tribuns commandent l’armée à la place de l’empereur"},{"id":"b","texte":"Trajan partage le pouvoir à égalité avec le Sénat"},{"id":"c","texte":"Les institutions de la République existent encore, mais l’empereur les cumule toutes"},{"id":"d","texte":"Rome est redevenue une république, dirigée par deux consuls élus"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**AVG**, pour *Augustus* : depuis qu’Octave l’a reçu en 27 av. J.-C., tous les empereurs portent ce titre."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 fois","explication":"**COS V** : consul pour la **5e fois**. V vaut 5 en chiffres romains."},{"cle":{"type":"zone","ids":["z5"]},"explication":"**DAC**, pour *Dacicus* : « vainqueur des Daces ». La Dacie (l’actuelle Roumanie) devient une province romaine en 106."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c2","i4":"c2"}},"explication":"IMP et DAC rappellent le **chef de guerre**, P M le **chef de la religion**, COS et TR P le maître de l’**État** : l’empereur réunit tous les pouvoirs."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les fonctions républicaines **subsistent, mais vidées de leur pouvoir** : c’est l’empereur qui les porte toutes. Et la monnaie, qui passe de main en main, le fait savoir dans tout l’Empire."}]$ex$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Une métropole vue du ciel","competence":"observer-schema","situation":"Vue d’avion, une très grande ville ressemble souvent à une cible : des cercles emboîtés autour d’un centre. Voici le croquis de Grandeville, une métropole imaginaire.","documents":[{"id":"croquis","type":"schema","titre":"Croquis de Grandeville","source":"Croquis simplifié, réalisé pour l’exercice.","largeur":340,"hauteur":300,"elements":[{"forme":"rect","x":10,"y":10,"l":320,"h":280,"arrondi":14,"teinte":"vert","motif":"clair"},{"forme":"cercle","cx":170,"cy":150,"r":128,"teinte":"gris","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":170,"cy":150,"r":86,"teinte":"ambre","motif":"clair","id":"z2","zone":true},{"forme":"cercle","cx":170,"cy":150,"r":38,"teinte":"corail","motif":"clair","id":"z3","zone":true},{"forme":"cercle","cx":222,"cy":112,"r":16,"teinte":"violet","motif":"plein","id":"z4","zone":true},{"forme":"emoji","x":170,"y":150,"emoji":"🏛️","taille":26},{"forme":"emoji","x":222,"y":112,"emoji":"🏢","taille":16},{"forme":"emoji","x":115,"y":120,"emoji":"🏘️","taille":20},{"forme":"emoji","x":150,"y":212,"emoji":"🏘️","taille":20},{"forme":"emoji","x":230,"y":182,"emoji":"🏘️","taille":20},{"forme":"emoji","x":95,"y":230,"emoji":"✈️","taille":22},{"forme":"emoji","x":275,"y":190,"emoji":"🛒","taille":20},{"forme":"emoji","x":235,"y":62,"emoji":"🏭","taille":20},{"forme":"emoji","x":35,"y":35,"emoji":"🌾","taille":20},{"forme":"emoji","x":305,"y":265,"emoji":"🌾","taille":20},{"forme":"emoji","x":305,"y":35,"emoji":"🌳","taille":20},{"forme":"emoji","x":35,"y":265,"emoji":"🌾","taille":20}],"legende":[{"teinte":"corail","motif":"clair","texte":"Centre-ville"},{"teinte":"violet","motif":"plein","texte":"Quartier d’affaires"},{"teinte":"ambre","motif":"clair","texte":"Banlieues"},{"teinte":"gris","motif":"clair","texte":"Périphéries"},{"teinte":"vert","motif":"clair","texte":"Campagne"}]}],"questions":[{"enonce":"Sur le croquis, touche la couronne des **banlieues**.","aide":"Aide-toi de la légende : cherche la couleur des banlieues, puis retrouve-la sur le croquis.","type":"zone","document":"croquis","multiple":false},{"enonce":"Range chaque élément du croquis dans la partie de la métropole où il se trouve.","aide":"Regarde dans quel cercle se trouve chaque petit dessin, puis lis la légende.","type":"categories","categories":[{"id":"c0","texte":"Centre-ville"},{"id":"c1","texte":"Quartier d’affaires"},{"id":"c2","texte":"Banlieues"},{"id":"c3","texte":"Périphéries"}],"items":[{"id":"i0","texte":"🏘️ Quartiers d’immeubles et de pavillons"},{"id":"i1","texte":"🏭 Zone industrielle"},{"id":"i2","texte":"🏛️ Musées et monuments historiques"},{"id":"i3","texte":"🛒 Centre commercial géant"},{"id":"i4","texte":"🏢 Tours de bureaux des grandes entreprises"},{"id":"i5","texte":"✈️ Aéroport"}]},{"enonce":"Pourquoi l’aéroport ✈️ de Grandeville a-t-il été construit en périphérie, et pas au centre-ville ?","aide":"Pense à la taille des pistes et au bruit d’un avion qui décolle.","type":"choix","options":[{"id":"a","texte":"Il a besoin d’immenses terrains, et le bruit des avions doit rester loin des logements"},{"id":"b","texte":"Le centre-ville est interdit aux voyageurs"},{"id":"c","texte":"Il n’y a aucune route dans le centre-ville"},{"id":"d","texte":"Les touristes préfèrent atterrir loin des monuments"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Les **banlieues** forment la couronne orangée qui entoure le centre-ville : c’est là que vivent la plupart des habitants."},{"cle":{"type":"categories","items":{"i0":"c2","i1":"c3","i2":"c0","i3":"c3","i4":"c1","i5":"c3"}},"explication":"Le **centre-ville** garde le patrimoine, le **quartier d’affaires** ses tours de bureaux, les **banlieues** les logements, et les **périphéries** l’aéroport, les zones commerciales et les usines."},{"cle":{"type":"choix","ids":["a"]},"explication":"**Il lui faut beaucoup de place, loin des logements.** En périphérie, les terrains sont vastes et moins chers qu’au centre, où chaque mètre carré coûte très cher."}]$ex$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Karim, trois heures par jour dans le train","competence":"calculer","situation":"Karim habite à Meaux, en Seine-et-Marne. Il travaille dans une tour du quartier d’affaires de La Défense, de l’autre côté de Paris. Comme des centaines de milliers de Franciliens, il fait ce trajet tous les jours.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Le matin de Karim","source":"Témoignage imaginé pour l’exercice.","blocs":["Mon réveil sonne à 6 h 15. À **6 h 50**, je ferme la porte de ma maison, à Meaux, et je marche jusqu’à la gare.","Je prends le train jusqu’à la gare de l’Est, à Paris, puis le RER jusqu’à La Défense. Aux heures de pointe, les wagons sont si pleins qu’on voyage debout, serrés comme des sardines.","J’arrive à mon bureau, au 30e étage d’une tour, à **8 h 20**. Le soir, je refais le même trajet dans l’autre sens. Mes enfants disent que je vis dans le train !"]},{"id":"horaires","type":"fiche","modele":"horaires","titre":"Les horaires du train de Karim","source":"Horaires simplifiés, imaginés pour l’exercice.","entete":"Meaux → Paris-Est","sousTitre":"En semaine","emoji":"🚆","lignes":[{"texte":"Départ de Meaux","valeur":"Arrivée à Paris-Est","gras":true},{"separateur":true},{"texte":"06:43","valeur":"07:17","id":"z1"},{"texte":"07:03","valeur":"07:37","id":"z2"},{"texte":"07:23","valeur":"07:57","id":"z3"},{"texte":"07:43","valeur":"08:17","id":"z4"}],"pied":"Marche de la maison de Karim à la gare : 10 min."}],"questions":[{"enonce":"Karim quitte sa maison à 6 h 50. Touche le **premier train** qu’il peut prendre.","aide":"Ajoute les 10 minutes de marche à son heure de départ : à quelle heure arrive-t-il à la gare ?","type":"zone","document":"horaires","multiple":false},{"enonce":"Combien de minutes dure le trajet en train, de Meaux à Paris-Est ?","aide":"Compte le temps qui s’écoule entre 7 h 03 et 7 h 37.","type":"nombre","unite":"min"},{"enonce":"Dans le Doc 1, touche l’expression qui désigne les moments où les transports sont les plus chargés.","aide":"C’est une expression de trois mots, dans le paragraphe 2.","type":"zone","document":"recit","multiple":true},{"enonce":"D’après le Doc 1, combien de minutes dure le trajet complet de Karim, de sa porte jusqu’à son bureau ?","aide":"Il part à 6 h 50 et arrive à 8 h 20. Compte d’abord jusqu’à 7 h 00, puis jusqu’à 8 h 00, puis jusqu’à 8 h 20.","type":"nombre","unite":"min"},{"enonce":"Complète le bilan de la journée de Karim.","aide":"Un aller dure une heure et demie. Et un pendule va… et vient !","type":"trous","segments":["Aller et retour, Karim passe ",0," heures par jour dans les transports. Ces trajets quotidiens entre le domicile et le travail s’appellent des migrations ",1,"."],"banque":["touristiques","pendulaires","saisonnières","6","1,5","3"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"6 h 50 + 10 min de marche = 7 h 00 à la gare. Le train de 6 h 43 est déjà parti : Karim prend celui de **7 h 03**."},{"cle":{"type":"nombre","valeur":34,"tolerance":0},"affichage":"34 min","explication":"De 7 h 03 à 7 h 37, il s’écoule **34 minutes**."},{"cle":{"type":"zone","ids":["m48","m49","m50"]},"explication":"Les **heures de pointe** : le matin et le soir, quand tout le monde part au travail ou en revient, les trains sont saturés."},{"cle":{"type":"nombre","valeur":90,"tolerance":0},"affichage":"90 min","explication":"De 6 h 50 à 8 h 20 : 10 min + 60 min + 20 min = **90 minutes**, soit une heure et demie."},{"cle":{"type":"trous","trous":[["3","trois"],["pendulaires"]]},"affichage":"3 · pendulaires","explication":"1 h 30 à l’aller + 1 h 30 au retour = **3 heures**. Ces allers-retours quotidiens sont des **migrations pendulaires**."}]$ex$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le siècle des villes","competence":"lire-graphique","situation":"En 1950, sur dix humains, trois seulement vivaient en ville. Que s’est-il passé depuis, et où vivent tous ces citadins ? Mène l’enquête avec deux documents de l’ONU.","documents":[{"id":"courbes","type":"graphique","forme":"courbe","titre":"Citadins et ruraux dans le monde, de 1950 à 2050","source":"Chiffres arrondis, ONU (2018). 2030 et 2050 : projections.","categories":["1950","1970","1990","2010","2030","2050"],"series":[{"nom":"Citadins","valeurs":[0.8,1.4,2.3,3.6,5.2,6.7],"teinte":"violet"},{"nom":"Ruraux","valeurs":[1.8,2.3,3,3.4,3.4,3.1],"teinte":"vert"}],"axeY":{"titre":"Population","unite":"milliards","min":0,"max":7,"pas":1},"axeX":{"titre":"Année"}},{"id":"villes","type":"graphique","forme":"barres-h","titre":"Dix grandes agglomérations du monde","source":"Chiffres arrondis, ONU (2018).","categories":["Tokyo","Delhi","Shanghai","São Paulo","Le Caire","Mumbai","New York","Lagos","Paris","Londres"],"series":[{"nom":"Habitants","valeurs":[37,29,26,22,20,20,19,13,11,9],"teinte":"violet"}],"axeY":{"titre":"Habitants","unite":"millions","min":0,"max":40,"pas":10},"valeurs":true}],"questions":[{"enonce":"Sur la courbe des citadins, touche la **première année** du graphique où ils sont plus nombreux que les ruraux.","aide":"Compare les deux courbes année par année : la violette doit passer au-dessus de la verte.","type":"zone","document":"courbes","multiple":false},{"enonce":"D’après les projections, combien de citadins y aura-t-il dans le monde en 2050 ?","aide":"Lis le dernier point de la courbe violette, entre deux graduations.","type":"nombre","unite":"milliards"},{"enonce":"Une **mégapole** compte plus de 10 millions d’habitants. Combien d’agglomérations du Doc 2 sont des mégapoles ?","aide":"Compte les barres qui dépassent 10 millions. Attention à la dernière !","type":"nombre","unite":"mégapoles"},{"enonce":"New York, Londres, Tokyo, Paris et Shanghai sont des **villes mondiales** : elles commandent l’économie de la planète. Touche celle qui n’est **pas** une mégapole.","aide":"Cherche, parmi ces cinq villes, celle qui a moins de 10 millions d’habitants.","type":"zone","document":"villes","multiple":false},{"enonce":"Que montrent **ensemble** ces deux documents ?","aide":"Le Doc 1 montre l’évolution des citadins ; le Doc 2, la taille des plus grandes villes.","type":"choix","options":[{"id":"a","texte":"Les plus grandes villes du monde sont toutes des villes mondiales"},{"id":"b","texte":"Le nombre de citadins baisse depuis 1990"},{"id":"c","texte":"Les ruraux sont de plus en plus nombreux, surtout autour des mégapoles"},{"id":"d","texte":"Les citadins sont de plus en plus nombreux, et beaucoup vivent dans des agglomérations géantes"}],"multiple":false}]}$ex$::jsonb,
