  ('972a14b2-f06b-557c-82f6-f68521a51e80'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux tarifs pour la piscine","competence":"resoudre","situation":"La piscine municipale propose deux façons de payer. Léo compte y aller souvent cette année et se demande quel tarif choisir.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"L’affiche à l’entrée de la piscine","entete":"Piscine des Tilleuls","sousTitre":"Tarifs de l’année","emoji":"🏊","teinte":"bleu","lignes":[{"texte":"**Tarif A** — sans carte :","valeur":"4 € l’entrée"},{"separateur":true},{"texte":"**Tarif B** — carte annuelle à 20 €,","valeur":"puis 2 € l’entrée"}],"pied":"La carte annuelle se paie une seule fois."},{"id":"tableau","type":"tableau","titre":"Le prix à payer selon le nombre d’entrées","colonnes":["Nombre d’entrées","1","5","10","15"],"lignes":[["Tarif A (€)",4,20,"?",60],["Tarif B (€)",22,30,40,"?"]],"enteteLignes":true}],"questions":[{"enonce":"Avec le **tarif A**, combien coûtent **10 entrées** ?","aide":"Au tarif A, chaque entrée coûte 4 €.","type":"nombre","unite":"€"},{"enonce":"Lequel de ces deux tarifs est une situation de **proportionnalité** ?","aide":"Dans une situation de proportionnalité, 0 entrée coûte 0 €, et deux fois plus d’entrées coûtent deux fois plus cher.","type":"choix","options":[{"id":"a","texte":"Le tarif A"},{"id":"b","texte":"Le tarif B"},{"id":"c","texte":"Les deux"},{"id":"d","texte":"Aucun des deux"}],"multiple":false},{"enonce":"Avec le **tarif B**, combien coûtent **15 entrées** ?","aide":"N’oublie pas la carte : 20 €, puis 2 € par entrée.","type":"nombre","unite":"€"},{"enonce":"Léo pense aller **15 fois** à la piscine cette année. Quel tarif doit-il choisir ?","aide":"Compare les deux prix dans la colonne « 15 » du tableau.","type":"choix","options":[{"id":"a","texte":"Le tarif A"},{"id":"b","texte":"Le tarif B"},{"id":"c","texte":"Les deux coûtent pareil"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 €","explication":"10 × 4 = **40 €**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Au tarif A, on multiplie toujours le nombre d’entrées par 4 : c’est proportionnel. Le tarif B part de 20 € (la carte) : 5 entrées coûtent 30 €, mais 10 entrées ne coûtent pas 60 €. **Seul le tarif A** est proportionnel."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 €","explication":"20 € pour la carte + 15 × 2 € = 20 + 30 = **50 €**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Pour 15 entrées : 60 € au tarif A, 50 € au tarif B. Le **tarif B** lui fait économiser 10 €."}]$ex$::jsonb),
