  ('ca4fdd67-bd21-5d3b-bccf-85dc817c718a'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La caisse du stand de gaufres","competence":"raisonner","situation":"À la fête de l’école, Maxime tient la caisse du stand des CM2 avec sa sœur Salomé. Leur vieille caisse enregistreuse fait parfois des siennes…","documents":[{"id":"carte","type":"fiche","modele":"menu","titre":"La carte du stand","entete":"Le Coin Gourmand","sousTitre":"Fête de l’école","emoji":"🧇","teinte":"ambre","lignes":[{"texte":"Crêpe au sucre","valeur":"1,50 €"},{"texte":"Gaufre","valeur":"2,20 €"},{"texte":"Jus de pomme","valeur":"0,80 €"},{"texte":"Barbe à papa","valeur":"2,50 €"}],"pied":"Les bénéfices financent la classe verte."},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Maxime et Salomé","participants":[{"nom":"Maxime","emoji":"👦","cote":"droite"},{"nom":"Salomé","emoji":"👧","cote":"gauche"}],"repliques":[{"qui":"Maxime","texte":"Une famille vient de prendre 3 gaufres et 2 jus de pomme."},{"qui":"Maxime","texte":"La caisse affiche 82,00 € 😱"},{"qui":"Salomé","texte":"Ça me paraît énorme… Vérifie avec un ordre de grandeur !"},{"qui":"Salomé","texte":"Et après, un groupe veut 4 formules « crêpe au sucre + jus de pomme »."}]}],"questions":[{"enonce":"Avec un **ordre de grandeur**, que peut-on dire des 82,00 € affichés pour 3 gaufres et 2 jus ?","aide":"Arrondis : une gaufre coûte environ 2 €, un jus environ 1 €.","type":"choix","options":[{"id":"a","texte":"C’est juste : on trouve environ 80 €"},{"id":"b","texte":"On ne peut pas le savoir sans calculatrice"},{"id":"c","texte":"C’est faux : on devrait trouver environ 8 €"},{"id":"d","texte":"C’est faux : on devrait trouver environ 800 €"}],"multiple":false},{"enonce":"Quel est le prix **exact** de cette commande ?","aide":"Les multiplications passent avant l’addition : calcule 3 × 2,20 et 2 × 0,80, puis additionne.","type":"nombre","unite":"€"},{"enonce":"Pour les **4 formules** « crêpe au sucre + jus de pomme », Maxime tape sur sa calculatrice : **4 × 1,50 + 0,80**. Qu’en penses-tu ?","aide":"La calculatrice respecte les priorités opératoires : que calcule-t-elle en premier ?","type":"choix","options":[{"id":"a","texte":"C’est faux : il compte 4 crêpes de trop"},{"id":"b","texte":"C’est juste : la calculatrice calcule dans l’ordre où c’est écrit"},{"id":"c","texte":"C’est juste : l’addition passe avant la multiplication"},{"id":"d","texte":"C’est faux : la multiplication passe d’abord, il ne compte qu’un seul jus"}],"multiple":false},{"enonce":"Calcule le bon prix des 4 formules : 4 × (1,50 + 0,80).","aide":"Les parenthèses d’abord : 1,50 + 0,80. Puis multiplie par 4.","type":"nombre","unite":"€"},{"enonce":"À la fin de la fête, Salomé compte **100** barbes à papa vendues. Combien ont-elles rapporté ?","aide":"Multiplier par 100, c’est déplacer la virgule de deux rangs vers la droite.","type":"nombre","unite":"€"}]}$ex$::jsonb,
