  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les soldes du Grenier du Sport","competence":"calculer","situation":"C’est la semaine des soldes au Grenier du Sport. Yanis lit l’affiche de l’entrée et fait ses calculs de tête, avec les **repères du cours** : 50 %, c’est la moitié ; 25 %, le quart ; 10 %, le dixième.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"L’affiche à l’entrée du magasin","source":"Magasin et prix imaginés pour l’exercice.","entete":"Le Grenier du Sport","sousTitre":"Grandes soldes d’été","emoji":"🏷️","teinte":"corail","lignes":[{"texte":"🏀 Ballon de basket (24 €) :","valeur":"−50 %","id":"z1"},{"texte":"🏓 Raquette de ping-pong (16 €) :","valeur":"−25 %","id":"z2"},{"texte":"🧢 Casquette (12 €) :","valeur":"−10 %","id":"z3"},{"texte":"🥤 Gourde isotherme (30 €) :","valeur":"−10 %","id":"z4"}],"pied":"Réduction calculée sur le prix entre parenthèses"}],"questions":[{"enonce":"De combien d’euros le prix du **ballon de basket** baisse-t-il ?","aide":"Prendre 50 % d’un prix, c’est en prendre la moitié : on divise par 2.","type":"nombre","unite":"€"},{"enonce":"Quel est le **nouveau prix** de la raquette de ping-pong ?","aide":"Calcule d’abord 25 % de 16 € (on divise par 4), puis enlève cette réduction du prix de départ.","type":"nombre","unite":"€"},{"enonce":"Sur l’affiche, touche l’article dont la réduction vaut exactement **1,20 €**.","aide":"1,20 €, c’est une petite réduction : regarde les articles à −10 %. Prendre 10 %, c’est diviser par 10.","type":"zone","document":"affiche","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 €","explication":"50 % de 24 €, c’est la moitié de 24 € : 24 ÷ 2 = **12 €** de réduction. Le ballon ne coûte plus que 12 €."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 €","explication":"25 % de 16 €, c’est 16 ÷ 4 = 4 €. Nouveau prix : 16 − 4 = **12 €**."},{"cle":{"type":"zone","ids":["z3"]},"explication":"10 % de 12 € = 12 ÷ 10 = **1,20 €** : c’est la **casquette**. Pour la gourde, 10 % de 30 € font 3 €."}]$ex$::jsonb),
  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce qu’il y a dans mon bol de céréales","competence":"analyser-document","situation":"Au petit déjeuner, Clémence lit l’étiquette de sa boîte de céréales au chocolat. Elle veut savoir quelle **part** de son bol de 40 g est faite de sucres, de fibres ou de glucides.","documents":[{"id":"etiquette","type":"fiche","modele":"etiquette","titre":"L’étiquette de la boîte de céréales","source":"Étiquette imaginée pour l’exercice.","entete":"Valeurs nutritionnelles","sousTitre":"Pour un bol de 40 g · Boîte de 500 g","lignes":[{"texte":"Énergie","valeur":"158 kcal","id":"z1"},{"texte":"Matières grasses","valeur":"2 g","id":"z2"},{"texte":"Glucides","valeur":"28 g","id":"z3","gras":true},{"texte":"   dont sucres","valeur":"12 g","id":"z4"},{"texte":"Fibres","valeur":"4 g","id":"z5"},{"texte":"Protéines","valeur":"5 g","id":"z6"},{"texte":"Sel","valeur":"0,2 g","id":"z7"}]}],"questions":[{"enonce":"Quel pourcentage du bol de 40 g représentent les **sucres** ?","aide":"Comme dans le cours : divise la masse de sucres par la masse du bol, puis écris le résultat en pourcentage (0,5 = 50 %).","type":"nombre","unite":"%"},{"enonce":"Touche la ligne de l’étiquette qui représente exactement **10 %** du bol.","aide":"Calcule d’abord 10 % de 40 g : on divise par 10. Puis cherche cette masse sur l’étiquette.","type":"zone","document":"etiquette","multiple":false},{"enonce":"La boîte entière contient **500 g** de céréales. Combien de grammes de sucres contient-elle ?","aide":"Les sucres font 30 % des céréales (question 1). 30 %, c’est 3 fois 10 % : commence par calculer 10 % de 500 g.","type":"nombre","unite":"g"},{"enonce":"Quelle part du bol représentent les **glucides** ?","aide":"Attention : 28 g, ce n’est pas 28 % ! Divise 28 par 40, puis écris le résultat en pourcentage.","type":"choix","options":[{"id":"a","texte":"7 %"},{"id":"b","texte":"70 %"},{"id":"c","texte":"0,7 %"},{"id":"d","texte":"28 %"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 %","explication":"12 ÷ 40 = 0,3 = **30 %** : près d’un tiers du bol, c’est du sucre."},{"cle":{"type":"zone","ids":["z5"]},"explication":"10 % de 40 g = 40 ÷ 10 = 4 g : ce sont les **fibres**."},{"cle":{"type":"nombre","valeur":150,"tolerance":0},"affichage":"150 g","explication":"10 % de 500 g = 50 g, donc 30 % = 3 × 50 = **150 g** de sucres dans la boîte."},{"cle":{"type":"choix","ids":["b"]},"explication":"28 ÷ 40 = 0,7 = **70 %** : les glucides font plus des deux tiers du bol."}]$ex$::jsonb),
  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux remises valent-elles une grosse remise ?","competence":"resoudre","situation":"Élise veut s’acheter des rollers à **120 €**. Dans son magasin, ils sont soldés. Son ami Nathan lui écrit : dans un autre magasin, les mêmes rollers ont aussi une remise… et même deux !","documents":[{"id":"affiche","type":"fiche","modele":"affiche","titre":"L’affiche du magasin d’Élise","source":"Magasins et prix imaginés pour l’exercice.","entete":"Planète Glisse","sousTitre":"Soldes d’hiver","emoji":"🛼","teinte":"violet","lignes":[{"texte":"Rollers Freestyle :","valeur":"120 €"},{"texte":"Remise immédiate :","valeur":"−30 %"}],"pied":"Remise calculée sur le prix affiché"},{"id":"sms","type":"dialogue","modele":"sms","titre":"Les messages de Nathan","participants":[{"nom":"Élise","emoji":"👧","cote":"gauche"},{"nom":"Nathan","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nathan","texte":"Chez Roule-Toujours, les mêmes rollers sont aussi à 120 € !"},{"qui":"Nathan","texte":"Il y a −20 % sur l’étiquette, puis encore −10 % en caisse avec la carte du magasin 😎"},{"qui":"Nathan","texte":"−20 % et −10 %, ça fait −30 %… c’est pareil que chez toi !"},{"qui":"Élise","texte":"Pas sûre… je vais calculer 🤔"}]}],"questions":[{"enonce":"Chez **Planète Glisse**, combien coûtent les rollers après la remise ?","aide":"Une réduction de 30 %, c’est 3 fois 10 %. Ou bien : on garde 70 % du prix, donc on multiplie par 0,7.","type":"nombre","unite":"€"},{"enonce":"Chez **Roule-Toujours**, complète le calcul de la première remise.","aide":"Enlever 20 %, c’est garder 100 − 20 = … % du prix. Multiplie ensuite 120 par 0,8.","type":"trous","segments":["Après −20 % sur l’étiquette, on garde ",0," % du prix : les rollers coûtent alors ",1," €."]},{"enonce":"En caisse, la carte enlève encore **10 %** de ce nouveau prix. Combien Élise paierait-elle chez **Roule-Toujours** ?","aide":"Les 10 % se calculent sur 96 €, pas sur 120 € : 10 % de 96 €, c’est 96 ÷ 10.","type":"nombre","unite":"€"},{"enonce":"Nathan écrit : « −20 % et −10 %, ça fait −30 %, c’est pareil ! » A-t-il raison ?","aide":"Compare tes réponses aux questions 1 et 3 : les deux prix sont-ils égaux ?","type":"choix","options":[{"id":"a","texte":"Non : la 2e remise porte sur 96 €, pas sur 120 €, donc elle fait gagner moins"},{"id":"b","texte":"Oui, mais seulement si on a la carte du magasin"},{"id":"c","texte":"Oui : 20 % + 10 % = 30 %, donc les deux prix sont égaux"},{"id":"d","texte":"Non : deux remises à la suite font toujours gagner plus qu’une seule"}],"multiple":false},{"enonce":"Élise achète ses rollers dans le magasin le moins cher. Combien économise-t-elle par rapport à l’autre magasin ?","aide":"Fais la différence entre les deux prix finaux (questions 1 et 3).","type":"nombre","unite":"€"}]}$ex$::jsonb,
